-- Formulas
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_727884ee00f6cb', 'subj_phys', 'electric-potential', 'Electric potential and capacitors', 'U = \frac{kq_1q_2}{r}, \quad V = \frac{kq}{r}, \quad \Delta U = q\Delta V, \quad C = \frac{Q}{V}, \quad U_C = \tfrac12 CV^2', 'Electric potential energy of two charges, potential of a point charge, energy change through a potential difference, and capacitors.', '[{"symbol":"V","meaning":"electric potential","unit":"V"},{"symbol":"C","meaning":"capacitance","unit":"F"},{"symbol":"U","meaning":"potential energy","unit":"J"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_10fe2eadbe10ec', 'subj_phys', 'dc-circuits', 'Kirchhoff''s rules and RC circuits', '\sum I_{in} = \sum I_{out}, \quad \sum \Delta V_{loop} = 0, \quad V_T = \varepsilon - Ir, \quad \tau = RC', 'Junction and loop rules, terminal voltage of a battery with internal resistance, and the RC time constant.', '[{"symbol":"\\varepsilon","meaning":"emf","unit":"V"},{"symbol":"r","meaning":"internal resistance","unit":"Ω"},{"symbol":"\\tau","meaning":"time constant","unit":"s"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_fc45e7b540bb79', 'subj_phys', 'interference', 'Interference and diffraction', 'd\sin\theta = m\lambda, \quad \Delta y = \frac{\lambda L}{d}, \quad a\sin\theta = m\lambda\ (\text{single-slit minima})', 'Bright fringes for two slits or a grating, fringe spacing on a distant screen, and dark fringes for a single slit.', '[{"symbol":"d","meaning":"slit separation","unit":"m"},{"symbol":"L","meaning":"screen distance","unit":"m"},{"symbol":"a","meaning":"slit width","unit":"m"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_0e1fb088df836c', 'subj_phys', 'modern-physics', 'Quantum and nuclear relations', '\lambda = \frac{h}{p}, \quad E_n = -\frac{13.6\ \text{eV}}{n^2}, \quad E = mc^2', 'de Broglie wavelength, hydrogen energy levels, and mass–energy equivalence (1 u = 931.5 MeV/c²).', '[{"symbol":"p","meaning":"momentum","unit":"kg·m/s"},{"symbol":"n","meaning":"energy level"}]', 'published');

-- Lesson: atomic-energy-levels
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_89740c30cda894', 'atomic-energy-levels', 'Energy in modern physics', 'Use energy-level diagrams to explain emission and absorption spectra, compute photon energies and wavelengths for hydrogen transitions, and find ionization energies.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a9befe34128160', 'les_89740c30cda894', 1, 'Explain discrete atomic energy levels and line spectra.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fb7c9ab6c7c6d1', 'les_89740c30cda894', 2, 'Use E_n = −13.6 eV/n² for hydrogen and ΔE = hf for transitions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_72f6f1a409cb1c', 'les_89740c30cda894', 3, 'Distinguish emission from absorption, and find ionization energy.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a9befe34128160', 'les_89740c30cda894', 'learn', 1, 'definition', '{"term":"Energy levels","body":"Electrons in atoms can only have certain energies. An electron dropping from a higher level to a lower one emits a photon with exactly the energy difference: $hf = E_{upper} - E_{lower}$. An atom absorbs only photons that match a gap. Each element''s set of gaps is a unique fingerprint."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fb7c9ab6c7c6d1', 'les_89740c30cda894', 'learn', 2, 'definition', '{"term":"Hydrogen","body":"$E_n = -\\frac{13.6\\ \\text{eV}}{n^2}$: $E_1 = -13.6$ eV (ground state), $E_2 = -3.40$ eV, $E_3 = -1.51$ eV. Ionizing from the ground state takes 13.6 eV. The shortcut $\\lambda\\ (\\text{nm}) = \\frac{1240}{E\\ (\\text{eV})}$ turns energies into wavelengths."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_72f6f1a409cb1c', 'les_89740c30cda894', 'learn', 3, 'worked_example', '{"title":"Hydrogen''s n = 3 → n = 2 transition","steps":[{"latex":"\\Delta E = 13.6\\left(\\tfrac14 - \\tfrac19\\right) \\approx 1.89\\ \\text{eV}","explanation":""},{"latex":"\\lambda = \\tfrac{1240}{1.89} \\approx 656\\ \\text{nm}","explanation":"The red H-alpha line that colors nebulae."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d835970af26651', 'les_89740c30cda894', 'learn', 4, 'worked_example', '{"title":"Hydrogen''s n = 2 → n = 1 transition","steps":[{"latex":"\\Delta E = 13.6\\left(1 - \\tfrac14\\right) = 10.2\\ \\text{eV}","explanation":""},{"latex":"\\lambda = \\tfrac{1240}{10.2} \\approx 122\\ \\text{nm}","explanation":"Ultraviolet."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ab6644066e233', 'les_89740c30cda894', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Neon signs, fireworks colors, sodium streetlights and lasers all come from specific transitions; astronomers read stars'' compositions from their absorption lines."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a9befe34128160', 'les_89740c30cda894', 1, 'practice', 'numeric', 2, 'How much energy ionizes hydrogen from the n = 2 level?', '{"answer":3.4,"unit":"eV"}', '[]', '$\frac{13.6}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fb7c9ab6c7c6d1', 'les_89740c30cda894', 2, 'practice', 'numeric', 2, 'How many different photon energies can be emitted as hydrogen electrons cascade from n = 4 to n = 1 by all possible routes?', '{"answer":6}', '[]', 'All pairs from 4 levels: $\binom{4}{2} = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_72f6f1a409cb1c', 'les_89740c30cda894', 3, 'practice', 'multiple_choice', 2, 'An atom with levels at −10, −6 and −4 eV absorbs a photon from the ground state. Which energy could be absorbed?', '{"choices":["2 eV","4 eV","5 eV","8 eV"],"answer":1}', '[]', 'Only gaps from −10 eV: 4 eV or 6 eV.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d835970af26651', 'les_89740c30cda894', 4, 'review', 'multiple_choice', 3, 'Lines in an emission spectrum appear because…', '{"choices":["electrons are particles","only certain energy gaps exist","light is a wave","atoms are hot"],"answer":1}', '[]', 'Discrete levels give discrete photon energies.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_89740c30cda894', (SELECT id FROM concepts WHERE slug = 'modern-physics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_89740c30cda894', (SELECT id FROM formulas WHERE slug = 'modern-physics'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_89740c30cda894', (SELECT id FROM formulas WHERE slug = 'photon-energy'), 2);

-- Lesson: atomic-nuclei
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_2255836cd8bcd3', 'atomic-nuclei', 'Properties of atomic nuclei', 'Describe nuclear composition with A, Z and N, explain isotopes and the strong force, and estimate nuclear size and density.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_602a7c5a709098', 'les_2255836cd8bcd3', 1, 'Use nuclear notation to find protons, neutrons and nucleons.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b1f078be8374d4', 'les_2255836cd8bcd3', 2, 'Describe isotopes and the strong nuclear force that binds nucleons.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_96872855231af2', 'les_2255836cd8bcd3', 3, 'Estimate nuclear radius R ≈ (1.2 fm)A^(1/3), and explain why nuclear density is nearly constant.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_602a7c5a709098', 'les_2255836cd8bcd3', 'learn', 1, 'definition', '{"term":"Notation","body":"$^A_Z\\text{X}$: $Z$ is the atomic number (protons, which identify the element), $A$ the mass number (protons + neutrons), and $N = A - Z$ the number of neutrons. Isotopes share $Z$ but differ in $N$: carbon-12 and carbon-14 both have 6 protons."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b1f078be8374d4', 'les_2255836cd8bcd3', 'learn', 2, 'definition', '{"term":"The strong force","body":"Protons repel each other electrically, yet nuclei hold together because of the strong nuclear force: it attracts nucleons very strongly but only over about 2 fm ($10^{-15}$ m). Heavy nuclei need extra neutrons, which add strong attraction without adding repulsion; past lead, no nucleus is truly stable."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96872855231af2', 'les_2255836cd8bcd3', 'learn', 3, 'definition', '{"term":"Size","body":"$R \\approx (1.2\\ \\text{fm})A^{1/3}$, so volume is proportional to $A$, and every nucleus has about the same enormous density, $2\\times10^{17}$ kg/m³."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_80a07f91a658e2', 'les_2255836cd8bcd3', 'learn', 4, 'worked_example', '{"title":"Uranium-238 and aluminum-27","steps":[{"latex":"N_U = 238 - 92 = 146\\ \\text{neutrons}","explanation":""},{"latex":"R_{Al} = 1.2(27)^{1/3} = 3.6\\ \\text{fm}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_de67b3db29c72d', 'les_2255836cd8bcd3', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Isotopes power carbon dating, medical imaging and nuclear energy; neutron stars are essentially giant nuclei at nuclear density."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_602a7c5a709098', 'les_2255836cd8bcd3', 1, 'practice', 'numeric', 1, 'How many neutrons are in iron-56 (Z = 26)?', '{"answer":30}', '[]', '$56 - 26$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b1f078be8374d4', 'les_2255836cd8bcd3', 2, 'practice', 'numeric', 2, 'Estimate the radius of a lead-208 nucleus in fm, to one decimal place.', '{"answer":7.1,"tolerance":0.05,"unit":"fm"}', '[]', '$1.2(208)^{1/3} \approx 7.1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96872855231af2', 'les_2255836cd8bcd3', 3, 'practice', 'multiple_choice', 2, 'Carbon-12 and carbon-14 differ in their number of…', '{"choices":["protons","electrons","neutrons","charge"],"answer":2}', '[]', 'Same element, same Z.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_80a07f91a658e2', 'les_2255836cd8bcd3', 4, 'review', 'multiple_choice', 3, 'The strong force acts…', '{"choices":["only between protons","between all nucleons over very short distances","at any distance","only on electrons"],"answer":1}', '[]', 'About 2 fm range.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_2255836cd8bcd3', (SELECT id FROM concepts WHERE slug = 'modern-physics'));

-- Lesson: boundary-behavior-polarization
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1e217dc82d3c67', 'boundary-behavior-polarization', 'Boundary behavior of waves and polarization', 'Predict reflected and transmitted pulses at boundaries, explain phase inversion, and use Malus''s law for polarized light.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bf30ac949f9ec3', 'les_1e217dc82d3c67', 1, 'Predict reflection at fixed and free ends and at boundaries between media.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_60378ba3e2409e', 'les_1e217dc82d3c67', 2, 'Explain when a reflected wave is inverted (a 180° phase shift).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_637722c37c9b65', 'les_1e217dc82d3c67', 3, 'Describe polarization and use Malus''s law, I = I₀cos²θ.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bf30ac949f9ec3', 'les_1e217dc82d3c67', 'learn', 1, 'definition', '{"term":"Reflection at boundaries","body":"At a fixed end, a pulse reflects inverted; at a free end, upright. At a junction between strings, part reflects and part transmits. Going into a slower (denser) medium, the reflection is inverted; going into a faster one, it''s upright. The transmitted pulse is never inverted, and its frequency stays the same."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_60378ba3e2409e', 'les_1e217dc82d3c67', 'learn', 2, 'definition', '{"term":"Light''s version","body":"Light reflecting off a medium with a higher index of refraction gets a 180° phase shift, which is key to thin-film colors."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_637722c37c9b65', 'les_1e217dc82d3c67', 'learn', 3, 'definition', '{"term":"Polarization","body":"Only transverse waves can be polarized. A polarizer passes only the component of the electric field along its axis. Unpolarized light loses half its intensity through the first polarizer; after that, Malus''s law gives $I = I_0\\cos^2\\theta$ for the angle $\\theta$ between the light''s polarization and the next axis."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ffaa002b22160', 'les_1e217dc82d3c67', 'learn', 4, 'worked_example', '{"title":"100 W/m² of unpolarized light passes two polarizers at 60° to each other","steps":[{"latex":"I_1 = \\tfrac{100}{2} = 50\\ \\text{W/m}^2","explanation":""},{"latex":"I_2 = 50\\cos^2 60° = 12.5\\ \\text{W/m}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d7b13a5438da7c', 'les_1e217dc82d3c67', 'learn', 5, 'callout', '{"tone":"note","title":"Glare","body":"Light reflecting off water is partly polarized horizontally, completely so at Brewster''s angle, $\\tan\\theta_B = n$ (about 53° for water). Polarized sunglasses block horizontal polarization."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eb108ef2c4ada3', 'les_1e217dc82d3c67', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"LCD screens, 3D movie glasses, photographers'' filters, and the proof that sound (longitudinal) can''t be polarized while light can."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bf30ac949f9ec3', 'les_1e217dc82d3c67', 1, 'practice', 'numeric', 2, 'Polarized light of 80 W/m² meets a polarizer at 30° to its polarization. Find the transmitted intensity.', '{"answer":60,"unit":"W/m²"}', '[]', '$80\cos^2 30° = 80(0.75)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_60378ba3e2409e', 'les_1e217dc82d3c67', 2, 'practice', 'multiple_choice', 2, 'A pulse travels from a light rope into a heavy rope. The reflected pulse is…', '{"choices":["upright","inverted","absent","faster"],"answer":1}', '[]', 'Slower medium: inverted reflection.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_637722c37c9b65', 'les_1e217dc82d3c67', 3, 'practice', 'multiple_choice', 2, 'Two polarizers are crossed at 90°. The light that gets through is…', '{"choices":["half","a quarter","none","all"],"answer":2}', '[]', '$\cos 90° = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2ffaa002b22160', 'les_1e217dc82d3c67', 4, 'review', 'multiple_choice', 3, 'Which wave cannot be polarized?', '{"choices":["light","radio waves","a wave on a string","sound in air"],"answer":3}', '[]', 'Sound in air is longitudinal.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1e217dc82d3c67', (SELECT id FROM concepts WHERE slug = 'waves'));

-- Lesson: capacitors
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f633a682949b44', 'capacitors', 'Capacitors', 'Define capacitance, compute parallel-plate capacitance and stored energy, see how dielectrics help, and combine capacitors.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_be9485479a9ca8', 'les_f633a682949b44', 1, 'Use C = Q/V and C = κε₀A/d.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_82ab4987b0406e', 'les_f633a682949b44', 2, 'Compute stored energy U = ½CV² = ½QV.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7cd40a419a2941', 'les_f633a682949b44', 3, 'Combine capacitors in parallel and series.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_be9485479a9ca8', 'les_f633a682949b44', 'learn', 1, 'definition', '{"term":"Capacitance","body":"A capacitor is two conductors that store equal and opposite charges $\\pm Q$. Capacitance $C = \\frac{Q}{V}$, in farads. For parallel plates, $C = \\frac{\\kappa\\varepsilon_0 A}{d}$ with $\\varepsilon_0 = 8.85\\times10^{-12}$ F/m; a dielectric of constant $\\kappa$ between the plates multiplies $C$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_82ab4987b0406e', 'les_f633a682949b44', 'learn', 2, 'worked_example', '{"title":"Plates of area 0.01 m², 1 mm apart, air between","steps":[{"latex":"C = \\tfrac{(8.85\\times10^{-12})(0.01)}{0.001} \\approx 88.5\\ \\text{pF}","explanation":"Tiny: a farad is enormous."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7cd40a419a2941', 'les_f633a682949b44', 'learn', 3, 'definition', '{"term":"Energy","body":"$U = \\frac12 CV^2 = \\frac12QV = \\frac{Q^2}{2C}$, stored in the electric field between the plates."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d1cea83534face', 'les_f633a682949b44', 'learn', 4, 'worked_example', '{"title":"A 100 μF capacitor charged to 9 V","steps":[{"latex":"U = \\tfrac12(100\\times10^{-6})(9^2) \\approx 4.05\\ \\text{mJ}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4f423c9001fd71', 'les_f633a682949b44', 'learn', 5, 'definition', '{"term":"Combinations","body":"Parallel (same V): $C = C_1 + C_2$. Series (same Q): $\\frac{1}{C} = \\frac{1}{C_1} + \\frac{1}{C_2}$, which is the reverse of the rules for resistors."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7c8b81badbcbaf', 'les_f633a682949b44', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Camera flashes dump stored energy in a millisecond, defibrillators store hundreds of joules, and touchscreens sense the change in capacitance from your finger."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_be9485479a9ca8', 'les_f633a682949b44', 1, 'practice', 'numeric', 2, 'Find the equivalent of 2 μF and 3 μF capacitors in series.', '{"answer":1.2,"unit":"μF"}', '[]', '$\frac{1}{1/2 + 1/3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_82ab4987b0406e', 'les_f633a682949b44', 2, 'practice', 'numeric', 2, 'A 5 μF capacitor holds 60 μC. Find its voltage.', '{"answer":12,"unit":"V"}', '[]', '$\frac{Q}{C}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7cd40a419a2941', 'les_f633a682949b44', 3, 'practice', 'multiple_choice', 2, 'Inserting a dielectric (κ = 3) into a capacitor connected to a battery…', '{"choices":["triples C and Q","triples V","cuts Q to a third","changes nothing"],"answer":0}', '[]', 'V is fixed by the battery; C triples, so Q = CV triples.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d1cea83534face', 'les_f633a682949b44', 4, 'review', 'multiple_choice', 3, 'Doubling the voltage on a capacitor multiplies its stored energy by…', '{"choices":["2","4","½","1"],"answer":1}', '[]', '$U \propto V^2$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f633a682949b44', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f633a682949b44', (SELECT id FROM formulas WHERE slug = 'electric-potential'), 1);

-- Lesson: charging-processes
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ccdfc4831bef3f', 'charging-processes', 'Conservation of charge and charging processes', 'Apply conservation of charge, and explain charging by friction, conduction and induction, polarization and grounding.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_da3b8307686639', 'les_ccdfc4831bef3f', 1, 'Apply conservation of charge to contact between conductors.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e390ed068f61e2', 'les_ccdfc4831bef3f', 2, 'Describe charging by friction, conduction and induction.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0984c2d0a5048d', 'les_ccdfc4831bef3f', 3, 'Explain polarization and grounding, and interpret electroscopes.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_da3b8307686639', 'les_ccdfc4831bef3f', 'learn', 1, 'definition', '{"term":"Conservation of charge","body":"The net charge of an isolated system never changes; charge only moves. When identical conducting spheres touch, they share their total charge equally."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e390ed068f61e2', 'les_ccdfc4831bef3f', 'learn', 2, 'worked_example', '{"title":"Identical spheres with +6 μC and −2 μC touch and then separate","steps":[{"latex":"Q_{total} = 6 + (-2) = 4\\ \\mu\\text{C}","explanation":""},{"latex":"\\text{each: } +2\\ \\mu\\text{C}","explanation":"Electrons flowed from the negative sphere to the positive one."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0984c2d0a5048d', 'les_ccdfc4831bef3f', 'learn', 3, 'definition', '{"term":"Three ways to charge","body":"Friction: rubbing transfers electrons between materials (rubber takes electrons from fur). Conduction: touching a charged object shares charge, so the object ends with the same sign. Induction: bring a charged rod near a conductor (without touching), ground the far side, remove the ground, then the rod; the conductor ends with the opposite sign."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7db5a5597ffca4', 'les_ccdfc4831bef3f', 'learn', 4, 'definition', '{"term":"Polarization and grounding","body":"A charged object shifts charges within a nearby neutral object (polarization), so the neutral object is attracted. Grounding connects an object to Earth, a huge reservoir that can supply or absorb electrons."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bfc393a02c6710', 'les_ccdfc4831bef3f', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Fuel trucks ground themselves before pumping, and electroscopes, whose leaves spread when charged, were the first instruments to detect radiation."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_da3b8307686639', 'les_ccdfc4831bef3f', 1, 'practice', 'numeric', 2, 'Three identical spheres hold +8, 0 and −2 nC. Sphere A touches B, then B touches C. Find C''s final charge.', '{"answer":1,"unit":"nC"}', '[]', 'A and B: +4 each. B and C: $\frac{4 - 2}{2} = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e390ed068f61e2', 'les_ccdfc4831bef3f', 2, 'practice', 'multiple_choice', 2, 'A negatively charged rod charges a sphere by induction. The sphere ends up…', '{"choices":["negative","positive","neutral","it depends on the sphere''s size"],"answer":1}', '[]', 'Grounding lets electrons be pushed away to Earth.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0984c2d0a5048d', 'les_ccdfc4831bef3f', 3, 'practice', 'multiple_choice', 2, 'A negatively charged rod touches a neutral electroscope. The leaves become…', '{"choices":["positive and spread","negative and spread","neutral","negative and collapse"],"answer":1}', '[]', 'Charging by conduction gives the same sign.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7db5a5597ffca4', 'les_ccdfc4831bef3f', 4, 'review', 'multiple_choice', 3, 'A charged comb picks up neutral bits of paper because…', '{"choices":["the paper is charged","the paper polarizes, and the nearer opposite charge is pulled more strongly","of gravity","of magnetism"],"answer":1}', '[]', 'Force falls off with distance.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ccdfc4831bef3f', (SELECT id FROM concepts WHERE slug = 'electrostatics'));

-- Lesson: compound-circuits
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_45d076a575935e', 'compound-circuits', 'Compound direct current circuits', 'Reduce series–parallel networks step by step, then work back out to find every current, voltage and power.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_85bab62248d5ec', 'les_45d076a575935e', 1, 'Reduce combination circuits to one equivalent resistance.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ffa8a041c0ba7d', 'les_45d076a575935e', 2, 'Work back through the network to find each branch''s current and voltage.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_51d067bca26d82', 'les_45d076a575935e', 3, 'Predict how adding or removing a branch changes the other currents.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_85bab62248d5ec', 'les_45d076a575935e', 'learn', 1, 'definition', '{"term":"Strategy","body":"Replace groups of resistors with their equivalents: series $R = R_1 + R_2$, parallel $\\frac1R = \\frac1{R_1} + \\frac1{R_2}$. Repeat until one resistor remains, find the total current, then expand back: series parts share the current, parallel parts share the voltage."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ffa8a041c0ba7d', 'les_45d076a575935e', 'learn', 2, 'worked_example', '{"title":"24 V across R₁ = 4 Ω in series with (R₂ = 6 Ω ∥ R₃ = 12 Ω)","steps":[{"latex":"R_{23} = \\left(\\tfrac16 + \\tfrac1{12}\\right)^{-1} = 4\\ \\Omega","explanation":""},{"latex":"R_{tot} = 4 + 4 = 8\\ \\Omega,\\ I = \\tfrac{24}{8} = 3\\ \\text{A}","explanation":""},{"latex":"V_{23} = 3(4) = 12\\ \\text{V}","explanation":"R₁ takes the other 12 V."},{"latex":"I_2 = \\tfrac{12}{6} = 2\\ \\text{A},\\ I_3 = \\tfrac{12}{12} = 1\\ \\text{A}","explanation":"These add back to 3 A."},{"latex":"P_1 = I^2R_1 = 9(4) = 36\\ \\text{W}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_51d067bca26d82', 'les_45d076a575935e', 'experiment', 3, 'activity', '{"activity":"circuit-builder","title":"Series and parallel building blocks"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1058cd8d47cf68', 'les_45d076a575935e', 'learn', 4, 'callout', '{"tone":"tip","title":"Predicting changes","body":"Removing R₃ leaves R₁ + R₂ = 10 Ω, so the total current drops to 2.4 A and R₂''s voltage rises from 12 V to 14.4 V. Changing one branch changes everything."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a63cbc80d2cd5', 'les_45d076a575935e', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Home circuits are parallel branches on one breaker; adding appliances lowers the total resistance and raises the current, until the breaker trips."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_85bab62248d5ec', 'les_45d076a575935e', 1, 'practice', 'numeric', 2, 'In the example, R₃ is removed. Find the new total current.', '{"answer":2.4,"unit":"A"}', '[]', '$\frac{24}{4 + 6}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ffa8a041c0ba7d', 'les_45d076a575935e', 2, 'practice', 'numeric', 2, 'Three 6 Ω resistors in parallel, in series with a 1 Ω resistor. Find the equivalent resistance.', '{"answer":3,"unit":"Ω"}', '[]', '$2 + 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_51d067bca26d82', 'les_45d076a575935e', 3, 'practice', 'numeric', 3, 'A 12 V battery drives 2 Ω in series with (3 Ω ∥ 6 Ω). Find the current through the 3 Ω resistor.', '{"answer":2,"unit":"A"}', '[]', '$R = 4$, $I = 3$ A, $V_\parallel = 6$ V, $\frac{6}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1058cd8d47cf68', 'les_45d076a575935e', 4, 'review', 'multiple_choice', 3, 'A bulb in a parallel branch burns out. The brightness of the other parallel bulbs (ideal battery, no series resistor)…', '{"choices":["increases","decreases","stays the same","drops to zero"],"answer":2}', '[]', 'Each still gets the full battery voltage.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_45d076a575935e', (SELECT id FROM concepts WHERE slug = 'circuits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_45d076a575935e', (SELECT id FROM formulas WHERE slug = 'dc-circuits'), 1);

-- Lesson: compton-scattering
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_443988114e70a7', 'compton-scattering', 'Compton scattering', 'Explain Compton scattering as a photon–electron collision, compute the wavelength shift, and see why it confirms photon momentum.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_271dd343ed39de', 'les_443988114e70a7', 1, 'Describe Compton scattering as an elastic collision between a photon and an electron.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_28aa93c8b2cf59', 'les_443988114e70a7', 2, 'Compute Δλ = (h/m_ec)(1 − cos θ).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2799c69b0a16da', 'les_443988114e70a7', 3, 'Explain how the result supports photons carrying momentum p = h/λ.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_271dd343ed39de', 'les_443988114e70a7', 'learn', 1, 'definition', '{"term":"The effect","body":"In 1923 Compton aimed X-rays at graphite and found the scattered X-rays had longer wavelengths, more so at larger angles. Waves can''t do that, but a photon colliding with an electron, conserving energy and momentum like billiard balls, does: the photon loses energy to the electron, so its wavelength grows."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_28aa93c8b2cf59', 'les_443988114e70a7', 'learn', 2, 'definition', '{"term":"Shift","body":"$\\Delta\\lambda = \\frac{h}{m_ec}(1 - \\cos\\theta)$, with $\\frac{h}{m_ec} = 2.43$ pm (the Compton wavelength). The shift ranges from 0 (no scattering) to 4.85 pm (straight back)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2799c69b0a16da', 'les_443988114e70a7', 'learn', 3, 'worked_example', '{"title":"71 pm X-rays scattered at 90°","steps":[{"latex":"\\Delta\\lambda = 2.43(1 - \\cos 90°) = 2.43\\ \\text{pm}","explanation":""},{"latex":"\\lambda'' = 71 + 2.43 \\approx 73.4\\ \\text{pm}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_216c409c874e4e', 'les_443988114e70a7', 'learn', 4, 'callout', '{"tone":"note","title":"Why X-rays?","body":"A 2.43 pm shift is about 3% of an X-ray''s wavelength but only 0.0005% of visible light''s, so the effect is only noticeable for very short wavelengths."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2396880f824e96', 'les_443988114e70a7', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Compton scattering dominates how X-rays and gamma rays deposit energy in tissue, which matters in radiation therapy and medical imaging."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_271dd343ed39de', 'les_443988114e70a7', 1, 'practice', 'numeric', 2, 'Find the Compton shift at 180°, in pm, to two decimal places.', '{"answer":4.85,"tolerance":0.02,"unit":"pm"}', '[]', '$2.43 \times 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_28aa93c8b2cf59', 'les_443988114e70a7', 2, 'practice', 'numeric', 2, 'Find the shift at 60°, in pm, to two decimal places.', '{"answer":1.21,"tolerance":0.01,"unit":"pm"}', '[]', '$2.43(1 - 0.5)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2799c69b0a16da', 'les_443988114e70a7', 3, 'practice', 'multiple_choice', 2, 'After Compton scattering, the photon''s energy is…', '{"choices":["greater","smaller","unchanged","zero"],"answer":1}', '[]', 'Longer wavelength means less energy.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_216c409c874e4e', 'les_443988114e70a7', 4, 'review', 'multiple_choice', 3, 'Compton scattering is strong evidence that photons…', '{"choices":["have mass","carry momentum","are waves only","travel slower than c"],"answer":1}', '[]', 'Momentum conservation in the collision explains the shift.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_443988114e70a7', (SELECT id FROM concepts WHERE slug = 'modern-physics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_443988114e70a7', (SELECT id FROM formulas WHERE slug = 'modern-physics'), 1);

-- Lesson: conservation-electric-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f73b040183b1c5', 'conservation-electric-energy', 'Conservation of electric energy', 'Use conservation of energy, ΔK = −qΔV, to find speeds of charged particles accelerated through potential differences.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b3ceafc845fede', 'les_f73b040183b1c5', 1, 'Apply K_i + qV_i = K_f + qV_f to charged particles.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8628e406178951', 'les_f73b040183b1c5', 2, 'Find final speeds after acceleration through a potential difference.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_dd1f0c7d3ace59', 'les_f73b040183b1c5', 3, 'Compare protons, electrons and alpha particles accelerated through the same voltage.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b3ceafc845fede', 'les_f73b040183b1c5', 'learn', 1, 'definition', '{"term":"Energy conservation","body":"With only electric forces doing work, $K_i + qV_i = K_f + qV_f$, so $\\Delta K = -q\\Delta V$. Positive charges speed up moving toward lower potential; negative charges speed up moving toward higher potential. In eV: a charge $ne$ through $V$ volts gains $nV$ eV."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8628e406178951', 'les_f73b040183b1c5', 'learn', 2, 'worked_example', '{"title":"A proton accelerated from rest through 2000 V","steps":[{"latex":"K = 2000\\ \\text{eV} = 3.20\\times10^{-16}\\ \\text{J}","explanation":""},{"latex":"v = \\sqrt{\\tfrac{2(3.20\\times10^{-16})}{1.67\\times10^{-27}}}","explanation":""},{"latex":"v \\approx 6.2\\times10^5\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_dd1f0c7d3ace59', 'les_f73b040183b1c5', 'learn', 3, 'worked_example', '{"title":"An alpha particle (charge +2e) through 1000 V","steps":[{"latex":"K = 2(1000) = 2000\\ \\text{eV}","explanation":"Same energy as the proton above, from half the voltage."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d404949840299b', 'les_f73b040183b1c5', 'learn', 4, 'callout', '{"tone":"note","title":"Why use eV","body":"Through the same voltage, an electron and a proton gain the same energy (in eV), but the electron is about 43 times faster: $\\sqrt{1836} \\approx 43$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_70ea192e207efc', 'les_f73b040183b1c5', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"X-ray tubes accelerate electrons through tens of kilovolts, and particle accelerators and mass spectrometers start by accelerating ions through known voltages."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b3ceafc845fede', 'les_f73b040183b1c5', 1, 'practice', 'numeric', 2, 'An electron accelerates from rest through 500 V. Find its kinetic energy, in units of $10^{-17}$ J.', '{"answer":8.01,"tolerance":0.01}', '[]', '$500 \times 1.602\times10^{-19}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8628e406178951', 'les_f73b040183b1c5', 2, 'practice', 'numeric', 3, 'A proton starts at 3 × 10⁵ m/s and moves through a potential rise of 300 V. Find its final speed, in units of $10^5$ m/s, to one decimal place.', '{"answer":1.8,"tolerance":0.05}', '[]', '$K_i = 7.52\times10^{-17}$ J; it loses $4.81\times10^{-17}$ J, leaving $2.71\times10^{-17}$ J, so $v \approx 1.8\times10^5$ m/s.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_dd1f0c7d3ace59', 'les_f73b040183b1c5', 3, 'practice', 'multiple_choice', 2, 'An electron released between charged plates moves toward…', '{"choices":["the negative plate","the positive plate (higher potential)","neither","the edge"],"answer":1}', '[]', 'Negative charges move toward higher potential.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d404949840299b', 'les_f73b040183b1c5', 4, 'review', 'multiple_choice', 3, 'An electron and a proton are accelerated through the same voltage. They gain the same…', '{"choices":["speed","kinetic energy","momentum","acceleration"],"answer":1}', '[]', '$K = |q|\Delta V$ with equal |q|.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f73b040183b1c5', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f73b040183b1c5', (SELECT id FROM formulas WHERE slug = 'electric-potential'), 1);

-- Lesson: diffraction-double-slit
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_37f4c20b403c1e', 'diffraction-double-slit', 'Diffraction and double-slit interference', 'Explain diffraction, find bright fringes in double-slit and grating patterns, fringe spacing on a screen, and single-slit dark fringes.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ce26aedaab8c27', 'les_37f4c20b403c1e', 1, 'Explain diffraction and why Young''s experiment shows light is a wave.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d71aecb40f295a', 'les_37f4c20b403c1e', 2, 'Use d sin θ = mλ and Δy = λL/d for double slits and gratings.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c4824c50d88fe6', 'les_37f4c20b403c1e', 3, 'Use a sin θ = mλ for single-slit minima.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ce26aedaab8c27', 'les_37f4c20b403c1e', 'learn', 1, 'definition', '{"term":"Diffraction","body":"Waves spread out after passing through an opening or around an edge, most noticeably when the opening is about the size of the wavelength. Light''s wavelength is tiny, which is why light seems to travel in straight lines."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d71aecb40f295a', 'les_37f4c20b403c1e', 'learn', 2, 'definition', '{"term":"Double slit","body":"Light from two slits interferes. The path difference to a point on the screen is $d\\sin\\theta$. Bright fringes appear where $d\\sin\\theta = m\\lambda$ and dark fringes where $d\\sin\\theta = (m + \\frac12)\\lambda$. For small angles, the fringes are evenly spaced: $\\Delta y = \\frac{\\lambda L}{d}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c4824c50d88fe6', 'les_37f4c20b403c1e', 'learn', 3, 'worked_example', '{"title":"550 nm light, slits 0.25 mm apart, screen 2 m away","steps":[{"latex":"\\Delta y = \\tfrac{(550\\times10^{-9})(2)}{0.25\\times10^{-3}} = 4.4\\ \\text{mm}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9282e8659799be', 'les_37f4c20b403c1e', 'learn', 4, 'definition', '{"term":"Gratings and single slits","body":"A diffraction grating has thousands of slits per millimeter, giving very sharp, widely spaced bright lines at the same $d\\sin\\theta = m\\lambda$. A single slit of width $a$ has dark fringes at $a\\sin\\theta = m\\lambda$ ($m \\ne 0$), with a broad central maximum."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7e80a223146df1', 'les_37f4c20b403c1e', 'learn', 5, 'worked_example', '{"title":"550 nm light on a grating with 600 lines/mm","steps":[{"latex":"d = \\tfrac{1}{600}\\ \\text{mm} \\approx 1.67\\ \\mu\\text{m}","explanation":""},{"latex":"\\theta_1 = \\sin^{-1}\\tfrac{550\\times10^{-9}}{1.67\\times10^{-6}} \\approx 19.3°","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ed9e45af7184ac', 'les_37f4c20b403c1e', 'experiment', 6, 'activity', '{"activity":"double-slit","title":"Change the wavelength and the slits","params":{"wavelength":550,"separation":0.25,"distance":2,"width":0.04}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ffa83204cbbc96', 'les_37f4c20b403c1e', 'experiment', 7, 'callout', '{"tone":"tip","title":"Try this","body":"Switch from red to violet light: the fringes squeeze together. Halve the slit separation: they spread twice as far. Widen the slits to see the single-slit envelope narrow."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a38d5418b5e38', 'les_37f4c20b403c1e', 'learn', 8, 'callout', '{"tone":"application","title":"Where this shows up","body":"Spectrometers use gratings to identify elements in stars, CDs show rainbow colors from their track spacing, and diffraction limits how fine a detail any microscope or telescope can resolve."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ce26aedaab8c27', 'les_37f4c20b403c1e', 1, 'practice', 'numeric', 2, 'Red light (650 nm) through slits 0.5 mm apart lands on a screen 1.5 m away. Find the fringe spacing in mm, to two decimal places.', '{"answer":1.95,"tolerance":0.01,"unit":"mm"}', '[]', '$\frac{650\times10^{-9}(1.5)}{0.5\times10^{-3}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d71aecb40f295a', 'les_37f4c20b403c1e', 2, 'practice', 'numeric', 3, 'Light through a 0.02 mm slit has its first dark fringe at 1.8°. Find λ, to the nearest 10 nm.', '{"answer":630,"tolerance":10,"unit":"nm"}', '[]', '$\lambda = a\sin\theta = 2\times10^{-5}\sin 1.8° \approx 628$ nm.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c4824c50d88fe6', 'les_37f4c20b403c1e', 3, 'practice', 'multiple_choice', 2, 'Reducing the slit separation makes the fringes…', '{"choices":["closer together","farther apart","unchanged","disappear"],"answer":1}', '[]', '$\Delta y \propto \frac{1}{d}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9282e8659799be', 'les_37f4c20b403c1e', 4, 'review', 'multiple_choice', 3, 'Young''s double-slit experiment showed that light…', '{"choices":["is made of particles","behaves as a wave","has no wavelength","travels instantly"],"answer":1}', '[]', 'Interference is a wave behavior.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_37f4c20b403c1e', (SELECT id FROM concepts WHERE slug = 'waves'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_37f4c20b403c1e', (SELECT id FROM formulas WHERE slug = 'interference'), 1);

-- Lesson: electric-potential-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7d33ba3759b7b8', 'electric-potential-energy', 'Electric potential energy', 'Compute the potential energy of systems of point charges, find the work needed to assemble them, and use electron-volts.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ec139b0c4d5fd3', 'les_7d33ba3759b7b8', 1, 'Compute U = kq₁q₂/r for a pair of charges, with signs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f034918d71f248', 'les_7d33ba3759b7b8', 2, 'Find the total potential energy of several charges by adding pairs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_18a52ebeec8f51', 'les_7d33ba3759b7b8', 3, 'Use the electron-volt, 1 eV = 1.602 × 10⁻¹⁹ J.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ec139b0c4d5fd3', 'les_7d33ba3759b7b8', 'learn', 1, 'definition', '{"term":"Potential energy of charges","body":"Two point charges have $U = \\frac{kq_1q_2}{r}$, zero when infinitely far apart. Like charges give $U > 0$ (work was needed to push them together); opposite charges give $U < 0$ (a bound system). For three or more charges, add $U$ for every pair."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f034918d71f248', 'les_7d33ba3759b7b8', 'learn', 2, 'worked_example', '{"title":"+2 μC and +3 μC, 0.1 m apart","steps":[{"latex":"U = \\tfrac{(8.99\\times10^9)(2\\times10^{-6})(3\\times10^{-6})}{0.1}","explanation":""},{"latex":"U \\approx 0.539\\ \\text{J}","explanation":"This is the work needed to bring them in from far apart."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_18a52ebeec8f51', 'les_7d33ba3759b7b8', 'learn', 3, 'definition', '{"term":"Electron-volts","body":"One electron-volt is the energy an electron gains moving through 1 V: $1\\ \\text{eV} = 1.602\\times10^{-19}$ J. Atomic energies are a few eV; nuclear energies are millions of eV (MeV)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a618a8ae3cdb73', 'les_7d33ba3759b7b8', 'learn', 4, 'worked_example', '{"title":"An electron accelerates from rest through 100 V","steps":[{"latex":"K = 100\\ \\text{eV} = 1.6\\times10^{-17}\\ \\text{J}","explanation":""},{"latex":"v = \\sqrt{\\tfrac{2(1.6\\times10^{-17})}{9.11\\times10^{-31}}}","explanation":""},{"latex":"v \\approx 5.9\\times10^6\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eefa9033e4dfeb', 'les_7d33ba3759b7b8', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Chemical bond energies, battery energy storage and the energy released when ions combine are all electric potential energy."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ec139b0c4d5fd3', 'les_7d33ba3759b7b8', 1, 'practice', 'numeric', 2, 'Find U for +1 μC and −1 μC charges 0.3 m apart, to three decimal places.', '{"answer":-0.03,"tolerance":0.0002,"unit":"J"}', '[]', '$\frac{8.99\times10^9(-10^{-12})}{0.3} \approx -0.030$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f034918d71f248', 'les_7d33ba3759b7b8', 2, 'practice', 'numeric', 2, 'Convert 5 eV to joules, in units of $10^{-19}$ J.', '{"answer":8.01,"tolerance":0.01}', '[]', '$5 \times 1.602$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_18a52ebeec8f51', 'les_7d33ba3759b7b8', 3, 'practice', 'multiple_choice', 2, 'Two electrons are released from rest near each other. As they fly apart, the system''s potential energy…', '{"choices":["increases","decreases, becoming kinetic energy","stays the same","becomes negative"],"answer":1}', '[]', 'Like charges: U falls as r grows.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a618a8ae3cdb73', 'les_7d33ba3759b7b8', 4, 'review', 'multiple_choice', 3, 'Three charges at the corners of a triangle. How many terms are in the total U?', '{"choices":["1","2","3","6"],"answer":2}', '[]', 'One for each pair.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7d33ba3759b7b8', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7d33ba3759b7b8', (SELECT id FROM formulas WHERE slug = 'electric-potential'), 1);

-- Lesson: electric-potential
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_727884ee00f6cb', 'electric-potential', 'Electric potential', 'Define electric potential and potential difference, compute potentials of point charges, relate a uniform field to ΔV/d, and read equipotential maps.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_60d89b93196156', 'les_727884ee00f6cb', 1, 'Define potential V = U/q and potential difference (voltage).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7a82b6975c22ee', 'les_727884ee00f6cb', 2, 'Compute V = kq/r and add potentials of several charges as scalars.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b6923d4b976de0', 'les_727884ee00f6cb', 3, 'Use E = ΔV/d in a uniform field and explain why equipotentials are perpendicular to field lines.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_60d89b93196156', 'les_727884ee00f6cb', 'learn', 1, 'definition', '{"term":"Potential","body":"Electric potential is potential energy per unit charge: $V = \\frac{U}{q}$, in volts (1 V = 1 J/C). Only differences matter physically: moving charge $q$ through $\\Delta V$ changes its energy by $\\Delta U = q\\Delta V$. For a point charge, $V = \\frac{kq}{r}$; for several, add the potentials (no vectors needed)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7a82b6975c22ee', 'les_727884ee00f6cb', 'learn', 2, 'worked_example', '{"title":"Potential 0.3 m from a +1 nC charge","steps":[{"latex":"V = \\tfrac{(8.99\\times10^9)(10^{-9})}{0.3} \\approx 30\\ \\text{V}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b6923d4b976de0', 'les_727884ee00f6cb', 'learn', 3, 'definition', '{"term":"Uniform fields and equipotentials","body":"Between parallel plates, the field is uniform and $E = \\frac{\\Delta V}{d}$ (so V/m = N/C). Equipotentials are surfaces of constant V. They are always perpendicular to field lines, and the field points toward lower potential; moving along an equipotential takes no work."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c46578c36fdca9', 'les_727884ee00f6cb', 'learn', 4, 'worked_example', '{"title":"12 V across plates 3 mm apart","steps":[{"latex":"E = \\tfrac{12}{0.003} = 4000\\ \\text{V/m}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0153b93a58cc28', 'les_727884ee00f6cb', 'experiment', 5, 'activity', '{"activity":"electric-potential","title":"Map the potential","params":{"q1":2,"q2":-2,"separation":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7181294fa61e2a', 'les_727884ee00f6cb', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"Put the probe exactly midway between +2 μC and −2 μC: the potential is zero, yet the field there isn''t. Then make both charges positive and compare."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b7cf0f26ace3c4', 'les_727884ee00f6cb', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Batteries are rated by potential difference, birds sit safely on one power line (no ΔV across them), and ECGs measure tiny potential differences across your chest."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_60d89b93196156', 'les_727884ee00f6cb', 1, 'practice', 'numeric', 2, 'Find V at the midpoint between +2 μC and +2 μC charges 4 m apart, in kV, to two decimal places.', '{"answer":17.98,"tolerance":0.02,"unit":"kV"}', '[]', '$2 \times \frac{8.99\times10^9 (2\times10^{-6})}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7a82b6975c22ee', 'les_727884ee00f6cb', 2, 'practice', 'numeric', 2, 'A proton moves from a 500 V point to a 200 V point. Find its kinetic energy gain in eV.', '{"answer":300,"unit":"eV"}', '[]', '$\Delta K = -q\Delta V = e(300\ \text{V})$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b6923d4b976de0', 'les_727884ee00f6cb', 3, 'practice', 'multiple_choice', 2, 'Field lines and equipotential lines meet at…', '{"choices":["0°","45°","90°","any angle"],"answer":2}', '[]', 'Moving along an equipotential takes no work, so there''s no field component along it.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c46578c36fdca9', 'les_727884ee00f6cb', 4, 'review', 'multiple_choice', 3, 'Where V = 0 between two charges, E must also be zero.', '{"choices":["true","false"],"answer":1}', '[]', 'At the midpoint of + and − charges, V = 0 but E points toward the negative charge.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_727884ee00f6cb', (SELECT id FROM concepts WHERE slug = 'electrostatics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_727884ee00f6cb', (SELECT id FROM formulas WHERE slug = 'electric-potential'), 1);

-- Lesson: entropy-second-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_d5f58ead223b50', 'entropy-second-law', 'Entropy and the second law of thermodynamics', 'Interpret entropy as a count of microscopic arrangements, compute entropy changes ΔS = Q/T, and apply the second law to heat flow, engines and refrigerators.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7ed4c305a35dd3', 'les_d5f58ead223b50', 1, 'Explain entropy as a measure of how many microscopic states fit a macroscopic state.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b33fbe441455f4', 'les_d5f58ead223b50', 2, 'Compute ΔS = Q/T at constant temperature.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d044271b51ff62', 'les_d5f58ead223b50', 3, 'Use the second law to explain heat flow direction and the limits on engines and refrigerators.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7ed4c305a35dd3', 'les_d5f58ead223b50', 'learn', 1, 'definition', '{"term":"Entropy","body":"Entropy $S$ measures disorder: how many microscopic arrangements produce the same overall state. Spread-out energy has far more arrangements than concentrated energy, so systems drift toward it. For heat $Q$ added at constant absolute temperature $T$: $\\Delta S = \\frac{Q}{T}$ (J/K)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b33fbe441455f4', 'les_d5f58ead223b50', 'learn', 2, 'definition', '{"term":"Second law","body":"The total entropy of an isolated system never decreases: $\\Delta S_{total} \\ge 0$. Heat flows spontaneously from hot to cold, never the reverse, and no cyclic engine can convert heat entirely into work."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d044271b51ff62', 'les_d5f58ead223b50', 'learn', 3, 'worked_example', '{"title":"Melting 1 kg of ice at 273 K","steps":[{"latex":"\\Delta S = \\tfrac{334{,}000}{273} \\approx 1220\\ \\text{J/K}","explanation":"Liquid water''s molecules have many more arrangements."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e001bf2edcc2e1', 'les_d5f58ead223b50', 'learn', 4, 'worked_example', '{"title":"1000 J flows from a 400 K reservoir to a 300 K reservoir","steps":[{"latex":"\\Delta S_{hot} = -\\tfrac{1000}{400} = -2.5\\ \\text{J/K}","explanation":""},{"latex":"\\Delta S_{cold} = +\\tfrac{1000}{300} \\approx 3.33\\ \\text{J/K}","explanation":""},{"latex":"\\Delta S_{total} \\approx +0.83\\ \\text{J/K} > 0","explanation":"The reverse flow would decrease total entropy, so it doesn''t happen on its own."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5850e49dea4160', 'les_d5f58ead223b50', 'learn', 5, 'definition', '{"term":"Refrigerators","body":"A refrigerator uses work $W$ to move heat $Q_c$ out of a cold space. Its coefficient of performance is $COP = \\frac{Q_c}{W}$, at most $\\frac{T_c}{T_h - T_c}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ec43948fb90fd3', 'les_d5f58ead223b50', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Every real process, from friction to mixing cream into coffee, increases total entropy. It''s why perpetual-motion machines are impossible and why heat pumps need electricity."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7ed4c305a35dd3', 'les_d5f58ead223b50', 1, 'practice', 'numeric', 2, 'Find the maximum COP of a freezer at 268 K in a 298 K kitchen, to two decimal places.', '{"answer":8.93,"tolerance":0.02}', '[]', '$\frac{268}{30}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b33fbe441455f4', 'les_d5f58ead223b50', 2, 'practice', 'numeric', 2, '500 J of heat leaves a 250 K object. Find its entropy change.', '{"answer":-2,"unit":"J/K"}', '[]', '$-\frac{500}{250}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d044271b51ff62', 'les_d5f58ead223b50', 3, 'practice', 'multiple_choice', 2, 'A refrigerator cools its inside, decreasing that entropy. This doesn''t violate the second law because…', '{"choices":["fridges are exempt","it dumps more entropy into the room","entropy can''t decrease","the food is cold"],"answer":1}', '[]', 'Total entropy still rises.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e001bf2edcc2e1', 'les_d5f58ead223b50', 4, 'review', 'multiple_choice', 3, 'Which has higher entropy?', '{"choices":["1 mol of ice at 0 °C","1 mol of water at 0 °C","1 mol of water vapor at 100 °C","They''re equal"],"answer":2}', '[]', 'Gas molecules have by far the most arrangements.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_d5f58ead223b50', (SELECT id FROM concepts WHERE slug = 'thermal-physics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_d5f58ead223b50', (SELECT id FROM formulas WHERE slug = 'heat-thermodynamics'), 1);

-- Lesson: fission-fusion
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_4bdbdc50d9b74a', 'fission-fusion', 'Fission, fusion and nuclear excitation', 'Explain fission chain reactions and fusion in stars, compute energy releases, and describe excited nuclei emitting gamma rays.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4ba7933461a22b', 'les_4bdbdc50d9b74a', 1, 'Describe fission of heavy nuclei and chain reactions.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e2583bd747bb29', 'les_4bdbdc50d9b74a', 2, 'Describe fusion of light nuclei and why it needs extreme temperatures.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e42e50a33b099a', 'les_4bdbdc50d9b74a', 3, 'Compute energy released per reaction and per kilogram, and describe nuclear excitation.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4ba7933461a22b', 'les_4bdbdc50d9b74a', 'learn', 1, 'definition', '{"term":"Fission","body":"A slow neutron absorbed by uranium-235 makes it split into two medium nuclei, releasing about 200 MeV and 2–3 neutrons. Those neutrons can trigger more fissions: a chain reaction. Reactors keep it steady with control rods that absorb neutrons; bombs let it run away."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e2583bd747bb29', 'les_4bdbdc50d9b74a', 'learn', 2, 'worked_example', '{"title":"Energy from fissioning 1 kg of uranium-235","steps":[{"latex":"N = \\tfrac{1\\ \\text{kg}}{235(1.6605\\times10^{-27}\\ \\text{kg})}","explanation":""},{"latex":"N \\approx 2.56\\times10^{24}","explanation":""},{"latex":"E = (2.56\\times10^{24})(200\\ \\text{MeV})","explanation":""},{"latex":"E \\approx 8.2\\times10^{13}\\ \\text{J}","explanation":"About 3 million times more than burning 1 kg of coal."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e42e50a33b099a', 'les_4bdbdc50d9b74a', 'learn', 3, 'definition', '{"term":"Fusion","body":"Light nuclei fuse into heavier ones, for example deuterium + tritium → helium-4 + neutron, releasing 17.6 MeV. Nuclei must get close enough for the strong force despite electric repulsion, which takes temperatures of millions of kelvin, like those in stars'' cores."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4c189ea7b95bc2', 'les_4bdbdc50d9b74a', 'learn', 4, 'definition', '{"term":"Nuclear excitation","body":"Like atoms, nuclei have discrete energy levels. A nucleus left excited after a decay or collision drops to its ground state by emitting a gamma-ray photon of a specific energy (keV to MeV)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_279d7f79e67831', 'les_4bdbdc50d9b74a', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Nuclear plants supply about 10% of the world''s electricity; the Sun fuses 600 million tonnes of hydrogen per second; fusion reactors like ITER aim to reproduce that on Earth."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4ba7933461a22b', 'les_4bdbdc50d9b74a', 1, 'practice', 'numeric', 2, 'Convert the 17.6 MeV released by one D–T fusion to joules, in units of $10^{-12}$ J, to two decimal places.', '{"answer":2.82,"tolerance":0.01}', '[]', '$17.6\times10^6 \times 1.602\times10^{-19}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e2583bd747bb29', 'les_4bdbdc50d9b74a', 2, 'practice', 'multiple_choice', 2, 'Control rods in a reactor work by…', '{"choices":["adding fuel","absorbing neutrons","cooling the water","speeding up neutrons"],"answer":1}', '[]', 'Fewer neutrons, fewer fissions.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e42e50a33b099a', 'les_4bdbdc50d9b74a', 3, 'practice', 'multiple_choice', 2, 'Fusion needs extremely high temperatures because…', '{"choices":["nuclei must overcome electric repulsion","neutrons need heat","the strong force is weak","light nuclei are unstable"],"answer":0}', '[]', 'Only very fast nuclei get close enough.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4c189ea7b95bc2', 'les_4bdbdc50d9b74a', 4, 'review', 'multiple_choice', 3, 'Both fission of uranium and fusion of hydrogen release energy because the products…', '{"choices":["have more mass","have higher binding energy per nucleon","are lighter elements","are radioactive"],"answer":1}', '[]', 'Both move toward iron''s peak.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_4bdbdc50d9b74a', (SELECT id FROM concepts WHERE slug = 'modern-physics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_4bdbdc50d9b74a', (SELECT id FROM formulas WHERE slug = 'modern-physics'), 1);

-- Lesson: kinetic-theory
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_60e8a63d1468d0', 'kinetic-theory', 'Kinetic theory of temperature and pressure', 'Explain gas pressure as molecular collisions, connect temperature to average kinetic energy, and compute rms speeds of gas molecules.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_52e9ccef088309', 'les_60e8a63d1468d0', 1, 'Explain pressure as the result of molecules colliding with container walls.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_42b33dfae06dfd', 'les_60e8a63d1468d0', 2, 'Use average kinetic energy K_avg = (3/2)k_BT.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8691d53d9ba7ad', 'les_60e8a63d1468d0', 3, 'Compute rms speed v_rms = √(3k_BT/m) and predict how it changes with temperature and mass.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_52e9ccef088309', 'les_60e8a63d1468d0', 'learn', 1, 'definition', '{"term":"The model","body":"An ideal gas is a huge number of tiny particles in random motion that collide elastically and don''t otherwise interact. Each collision with a wall gives it a small impulse; the average force per area from billions of collisions is the pressure."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_42b33dfae06dfd', 'les_60e8a63d1468d0', 'learn', 2, 'definition', '{"term":"Temperature","body":"Absolute temperature measures the average translational kinetic energy per molecule: $K_{avg} = \\frac32 k_B T$, with $k_B = 1.38\\times10^{-23}$ J/K. So $v_{rms} = \\sqrt{\\frac{3k_BT}{m}}$: lighter molecules move faster at the same temperature."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8691d53d9ba7ad', 'les_60e8a63d1468d0', 'learn', 3, 'worked_example', '{"title":"Nitrogen (N₂, m = 4.65 × 10⁻²⁶ kg) at 300 K","steps":[{"latex":"K_{avg} = \\tfrac32(1.38\\times10^{-23})(300)","explanation":""},{"latex":"K_{avg} \\approx 6.21\\times10^{-21}\\ \\text{J}","explanation":""},{"latex":"v_{rms} = \\sqrt{\\tfrac{3(1.38\\times10^{-23})(300)}{4.65\\times10^{-26}}}","explanation":""},{"latex":"v_{rms} \\approx 517\\ \\text{m/s}","explanation":"Faster than the speed of sound, though each molecule zigzags constantly."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_66146613080820', 'les_60e8a63d1468d0', 'experiment', 4, 'activity', '{"activity":"ideal-gas","title":"Heat the gas and watch the pressure"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d15dc4055a8a5', 'les_60e8a63d1468d0', 'learn', 5, 'callout', '{"tone":"note","title":"Distribution","body":"Molecules don''t all share one speed: the Maxwell–Boltzmann distribution spreads them out, and a few are much faster than average. Those fast ones drive evaporation."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4398bb4690818e', 'les_60e8a63d1468d0', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Hydrogen and helium escape Earth''s atmosphere because their light molecules reach escape speed more often; tire pressure rises on a hot day."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_52e9ccef088309', 'les_60e8a63d1468d0', 1, 'practice', 'numeric', 2, 'The absolute temperature of a gas doubles. By what factor does v_rms change? Give a decimal to three places.', '{"answer":1.414,"tolerance":0.002}', '[]', '$v_{rms} \propto \sqrt T$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_42b33dfae06dfd', 'les_60e8a63d1468d0', 2, 'practice', 'numeric', 2, 'Find the average kinetic energy per molecule at 600 K, in units of $10^{-21}$ J.', '{"answer":12.42,"tolerance":0.02}', '[]', '$\frac32(1.38\times10^{-23})(600)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8691d53d9ba7ad', 'les_60e8a63d1468d0', 3, 'practice', 'multiple_choice', 2, 'Helium and oxygen are at the same temperature. Compared with oxygen molecules, helium atoms have…', '{"choices":["the same average KE and higher rms speed","higher average KE","lower rms speed","the same rms speed"],"answer":0}', '[]', 'Same T, same $K_{avg}$; lighter mass, faster.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_66146613080820', 'les_60e8a63d1468d0', 4, 'review', 'multiple_choice', 3, 'Gas in a rigid container is heated. Pressure rises because molecules…', '{"choices":["get bigger","hit the walls harder and more often","attract each other more","multiply"],"answer":1}', '[]', 'Higher speed means a larger impulse per collision and more collisions per second.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_60e8a63d1468d0', (SELECT id FROM concepts WHERE slug = 'thermal-physics'));

-- Lesson: kirchhoff-junction-rule
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8ca0633aeb432f', 'kirchhoff-junction-rule', 'Kirchhoff''s junction rule and conservation of charge', 'Apply the junction rule, then combine junction and loop equations to solve circuits with two batteries in different branches.', 40, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0d3c53d5960135', 'les_8ca0633aeb432f', 1, 'State the junction rule: current in equals current out.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6c2c83328fa8ba', 'les_8ca0633aeb432f', 2, 'Write junction and loop equations for multi-loop circuits.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_28a43230942f98', 'les_8ca0633aeb432f', 3, 'Solve them and interpret negative currents.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0d3c53d5960135', 'les_8ca0633aeb432f', 'learn', 1, 'definition', '{"term":"Junction rule","body":"Charge can''t pile up at a junction, so $\\sum I_{in} = \\sum I_{out}$. With $n$ junctions you get $n - 1$ independent junction equations; loops supply the rest."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6c2c83328fa8ba', 'les_8ca0633aeb432f', 'learn', 2, 'worked_example', '{"title":"Three branches join two nodes A (top) and B (bottom, 0 V): left, a 10 V battery with 2 Ω; middle, a 4 Ω resistor; right, a 4 V battery with 2 Ω. Both batteries have + toward A","steps":[{"latex":"I_1 + I_2 = I_3","explanation":"Junction A: currents up the battery branches and down the middle."},{"latex":"I_1 = \\tfrac{10 - V_A}{2},\\ I_2 = \\tfrac{4 - V_A}{2},\\ I_3 = \\tfrac{V_A}{4}","explanation":"Each branch''s loop with B."},{"latex":"\\tfrac{10 - V_A}{2} + \\tfrac{4 - V_A}{2} = \\tfrac{V_A}{4}","explanation":""},{"latex":"V_A = 5.6\\ \\text{V}","explanation":""},{"latex":"I_1 = 2.2\\ \\text{A},\\ I_2 = -0.8\\ \\text{A},\\ I_3 = 1.4\\ \\text{A}","explanation":"I₂ is negative: current flows backward through the 4 V battery, charging it."}],"check":"Check: $2.2 + (-0.8) = 1.4$. ✓"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_28a43230942f98', 'les_8ca0633aeb432f', 'learn', 3, 'callout', '{"tone":"tip","title":"Strategy","body":"Label each branch current with a guessed direction, write the junction equations, write enough loop equations to match the number of unknowns, and solve. Never redraw directions mid-problem; let the signs tell you."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c33ce7c3da779e', 'les_8ca0633aeb432f', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Car electrical systems (alternator, battery and loads in parallel) and solar panels with storage batteries are multi-loop circuits solved exactly this way."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0d3c53d5960135', 'les_8ca0633aeb432f', 1, 'practice', 'numeric', 1, '3 A and 2 A flow into a junction; one wire carries 4 A out. Find the current in the other outgoing wire.', '{"answer":1,"unit":"A"}', '[]', '$5 - 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6c2c83328fa8ba', 'les_8ca0633aeb432f', 2, 'practice', 'numeric', 3, 'In the example, replace the 4 V battery with a 10 V one. Find the middle-branch current.', '{"answer":2,"unit":"A"}', '[]', '$\frac{10 - V}{2} \times 2 = \frac{V}{4}$ gives $V = 8$ V, so $I_3 = 2$ A.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_28a43230942f98', 'les_8ca0633aeb432f', 3, 'practice', 'multiple_choice', 2, 'A calculated branch current comes out −0.5 A. This means…', '{"choices":["an error","it flows opposite to the assumed direction","the battery is dead","the junction rule failed"],"answer":1}', '[]', 'Signs encode direction.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c33ce7c3da779e', 'les_8ca0633aeb432f', 4, 'review', 'multiple_choice', 3, 'The junction rule follows from conservation of…', '{"choices":["energy","charge","momentum","power"],"answer":1}', '[]', 'Charge doesn''t accumulate at a point.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8ca0633aeb432f', (SELECT id FROM concepts WHERE slug = 'circuits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_8ca0633aeb432f', (SELECT id FROM formulas WHERE slug = 'dc-circuits'), 1);

-- Lesson: kirchhoff-loop-rule
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_71f55ae8a25165', 'kirchhoff-loop-rule', 'Kirchhoff''s loop rule', 'Apply conservation of energy around closed loops, with sign conventions for batteries and resistors, including loops with more than one battery.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c15f96d9aaa9f7', 'les_71f55ae8a25165', 1, 'State the loop rule: the sum of potential changes around any closed loop is zero.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cd41cf84c4e6b2', 'les_71f55ae8a25165', 2, 'Apply sign conventions for batteries and resistors.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a52eeb607c1d62', 'les_71f55ae8a25165', 3, 'Solve single-loop circuits with several batteries.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c15f96d9aaa9f7', 'les_71f55ae8a25165', 'learn', 1, 'definition', '{"term":"Loop rule","body":"Going around any closed loop and returning to the start, the potential must return to its original value: $\\sum\\Delta V = 0$. It''s conservation of energy for charges."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cd41cf84c4e6b2', 'les_71f55ae8a25165', 'learn', 2, 'definition', '{"term":"Signs","body":"Choose a current direction and a direction to walk the loop. Crossing a battery from − to +: $+\\varepsilon$. Crossing a resistor in the direction of the current: $-IR$ (potential drops). Against the current: $+IR$. A negative answer just means the current flows the other way."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a52eeb607c1d62', 'les_71f55ae8a25165', 'learn', 3, 'worked_example', '{"title":"A 12 V battery and a 3 V battery oppose each other in one loop with 1 Ω and 2 Ω resistors","steps":[{"latex":"+12 - I(1) - 3 - I(2) = 0","explanation":"Walking clockwise with the assumed current."},{"latex":"I = \\tfrac{9}{3} = 3\\ \\text{A}","explanation":"The 3 V battery is being charged."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4ce91b1a213a40', 'les_71f55ae8a25165', 'learn', 4, 'callout', '{"tone":"note","title":"Potential maps","body":"Plotting the potential at each point around the loop shows rises at batteries and drops at resistors, ending where it started."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_61972fa1f7edfa', 'les_71f55ae8a25165', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Jump-starting a car connects batteries in a loop, and the loop rule shows why reversing the cables is dangerous: the emfs add instead of cancelling."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c15f96d9aaa9f7', 'les_71f55ae8a25165', 1, 'practice', 'numeric', 2, 'A 9 V battery drives current through 1 Ω, 2 Ω and 6 Ω in series. Find the voltage drop across the 6 Ω resistor.', '{"answer":6,"unit":"V"}', '[]', '$I = 1$ A, so $1 \times 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cd41cf84c4e6b2', 'les_71f55ae8a25165', 2, 'practice', 'numeric', 3, 'Two 6 V batteries are connected in series, but one is accidentally reversed, with a 4 Ω resistor. Find the current.', '{"answer":0,"unit":"A"}', '[]', 'The emfs cancel.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a52eeb607c1d62', 'les_71f55ae8a25165', 3, 'practice', 'multiple_choice', 2, 'Walking through a resistor opposite to the current direction, the potential…', '{"choices":["drops by IR","rises by IR","doesn''t change","drops by ε"],"answer":1}', '[]', 'Current flows from high to low potential.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4ce91b1a213a40', 'les_71f55ae8a25165', 4, 'review', 'multiple_choice', 3, 'The loop rule is a statement of conservation of…', '{"choices":["charge","energy","momentum","mass"],"answer":1}', '[]', 'Potential is energy per charge.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_71f55ae8a25165', (SELECT id FROM concepts WHERE slug = 'circuits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_71f55ae8a25165', (SELECT id FROM formulas WHERE slug = 'dc-circuits'), 1);

-- Lesson: law-of-reflection
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_457a29220bf060', 'law-of-reflection', 'Reflection', 'Apply the law of reflection with ray diagrams, distinguish specular from diffuse reflection, and solve plane-mirror problems including mirror height and multiple images.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_ba6d5907694081', 'les_457a29220bf060', 1, 'Apply θ_r = θ_i using normals and ray diagrams.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cc3aac7484af51', 'les_457a29220bf060', 2, 'Distinguish specular and diffuse reflection.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c4ab0695ad97ef', 'les_457a29220bf060', 3, 'Locate plane-mirror images, find the minimum mirror height and count images between two mirrors.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ba6d5907694081', 'les_457a29220bf060', 'learn', 1, 'definition', '{"term":"Law of reflection","body":"The incident ray, the reflected ray and the normal all lie in one plane, and $\\theta_r = \\theta_i$, measured from the normal. A smooth surface reflects parallel rays in parallel (specular, giving images); a rough surface scatters them (diffuse, letting you see the surface itself from any angle)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cc3aac7484af51', 'les_457a29220bf060', 'learn', 2, 'definition', '{"term":"Plane-mirror images","body":"The image is virtual, upright, the same size as the object, and as far behind the mirror as the object is in front, with front and back reversed."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c4ab0695ad97ef', 'les_457a29220bf060', 'learn', 3, 'worked_example', '{"title":"What''s the shortest mirror that shows all of a 1.8 m person?","steps":[{"latex":"h_{mirror} = \\tfrac{1.8}{2} = 0.9\\ \\text{m}","explanation":"Rays from your feet to your eyes reflect halfway down; the result doesn''t depend on distance."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_93f505d029ec8a', 'les_457a29220bf060', 'learn', 4, 'worked_example', '{"title":"Two plane mirrors meet at 60°. How many images of an object between them?","steps":[{"latex":"N = \\tfrac{360°}{60°} - 1 = 5","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ce0c911827994c', 'les_457a29220bf060', 'experiment', 5, 'activity', '{"activity":"ray-optics","title":"From plane to curved mirrors","params":{"optic":"concave","focal":20,"object":10}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a5534b4c4be5e2', 'les_457a29220bf060', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Corner reflectors left on the Moon by Apollo astronauts send laser light straight back to Earth, and bike reflectors use the same geometry."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ba6d5907694081', 'les_457a29220bf060', 1, 'practice', 'numeric', 2, 'A ray strikes a mirror at 35° to the surface. Find the angle of reflection measured from the normal.', '{"answer":55,"unit":"°"}', '[]', '$90 - 35$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cc3aac7484af51', 'les_457a29220bf060', 2, 'practice', 'numeric', 2, 'How many images form between two mirrors at 90°?', '{"answer":3}', '[]', '$\frac{360}{90} - 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c4ab0695ad97ef', 'les_457a29220bf060', 3, 'practice', 'multiple_choice', 2, 'You walk toward a plane mirror at 1 m/s. Your image approaches you at…', '{"choices":["1 m/s","2 m/s","0.5 m/s","0 m/s"],"answer":1}', '[]', 'You and your image both close in.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_93f505d029ec8a', 'les_457a29220bf060', 4, 'review', 'multiple_choice', 3, 'A wet road at night looks darker and glares because…', '{"choices":["water absorbs light","it switches from diffuse to specular reflection","water refracts all light","it''s hotter"],"answer":1}', '[]', 'Water fills the rough surface into a smooth one.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_457a29220bf060', (SELECT id FROM concepts WHERE slug = 'optics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_457a29220bf060', (SELECT id FROM formulas WHERE slug = 'optics-equations'), 1);

-- Lesson: magnetic-fields-moving-charges
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_141193969acfab', 'magnetic-fields-moving-charges', 'Magnetic fields from moving charges', 'Find the circular paths of charges in magnetic fields, use velocity selectors, and compute the forces between parallel current-carrying wires.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_206328d1731d0a', 'les_141193969acfab', 1, 'Find the radius r = mv/(qB) and period T = 2πm/(qB) of a charge circling in a uniform field.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7f53bcb559e36c', 'les_141193969acfab', 2, 'Use crossed fields as a velocity selector, v = E/B.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e2f6e22d4f7d33', 'les_141193969acfab', 3, 'Compute the force between parallel wires and predict attraction or repulsion.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_206328d1731d0a', 'les_141193969acfab', 'learn', 1, 'definition', '{"term":"Circular motion in a field","body":"A charge moving perpendicular to a uniform field feels a force $qvB$ at right angles to its velocity, so it moves in a circle: $qvB = \\frac{mv^2}{r}$, giving $r = \\frac{mv}{qB}$. The period $T = \\frac{2\\pi m}{qB}$ doesn''t depend on speed."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7f53bcb559e36c', 'les_141193969acfab', 'learn', 2, 'worked_example', '{"title":"A proton at 1 × 10⁶ m/s in a 0.5 T field","steps":[{"latex":"r = \\tfrac{(1.67\\times10^{-27})(10^6)}{(1.6\\times10^{-19})(0.5)}","explanation":""},{"latex":"r \\approx 0.021\\ \\text{m}","explanation":""},{"latex":"r_e \\approx 1.1\\times10^{-5}\\ \\text{m}","explanation":"An electron at the same speed: about 1800 times smaller, and circling the other way."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e2f6e22d4f7d33', 'les_141193969acfab', 'learn', 3, 'definition', '{"term":"Velocity selector","body":"With an electric field and a magnetic field at right angles, the forces $qE$ and $qvB$ cancel only for $v = \\frac{E}{B}$; particles at other speeds are deflected away."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_269db8779a5d79', 'les_141193969acfab', 'learn', 4, 'definition', '{"term":"Parallel wires","body":"Each current sits in the other''s field ($B = \\frac{\\mu_0 I}{2\\pi d}$), so the force per length is $\\frac{F}{L} = \\frac{\\mu_0 I_1 I_2}{2\\pi d}$. Currents in the same direction attract; opposite directions repel."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eb8cbc208eebde', 'les_141193969acfab', 'learn', 5, 'worked_example', '{"title":"Two wires 0.1 m apart, each carrying 10 A in the same direction","steps":[{"latex":"\\tfrac{F}{L} = \\tfrac{(4\\pi\\times10^{-7})(10)(10)}{2\\pi(0.1)}","explanation":""},{"latex":"\\tfrac{F}{L} = 2\\times10^{-4}\\ \\text{N/m}","explanation":"Attractive."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9471101c140e67', 'les_141193969acfab', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Mass spectrometers sort ions by the radius of their paths, cyclotrons use the speed-independent period, and Earth''s field funnels charged particles toward the poles to make auroras."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_206328d1731d0a', 'les_141193969acfab', 1, 'practice', 'numeric', 2, 'A velocity selector has E = 2000 V/m and B = 0.01 T. Find the selected speed.', '{"answer":200000,"unit":"m/s"}', '[]', '$\frac{E}{B}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7f53bcb559e36c', 'les_141193969acfab', 2, 'practice', 'numeric', 3, 'An alpha particle (m = 6.64 × 10⁻²⁷ kg, q = 3.2 × 10⁻¹⁹ C) moves at 2 × 10⁶ m/s perpendicular to a 1 T field. Find r in cm, to two decimal places.', '{"answer":4.15,"tolerance":0.02,"unit":"cm"}', '[]', '$\frac{6.64\times10^{-27}(2\times10^6)}{3.2\times10^{-19}} \approx 0.0415$ m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e2f6e22d4f7d33', 'les_141193969acfab', 3, 'practice', 'multiple_choice', 2, 'Doubling a proton''s speed in a uniform field changes its period by a factor of…', '{"choices":["2","½","1","4"],"answer":2}', '[]', '$T = \frac{2\pi m}{qB}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_269db8779a5d79', 'les_141193969acfab', 4, 'review', 'multiple_choice', 3, 'Two parallel wires carry currents in opposite directions. They…', '{"choices":["attract","repel","feel no force","twist"],"answer":1}', '[]', 'Opposite currents repel.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_141193969acfab', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_141193969acfab', (SELECT id FROM formulas WHERE slug = 'magnetism-induction'), 1);

-- Lesson: magnetic-flux
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_bb769aa3ece400', 'magnetic-flux', 'Magnetic flux', 'Compute magnetic flux through loops at any angle, find motional emf ε = BLv, and use Lenz''s law to find the direction of induced currents.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_16e3953ba2dab8', 'les_bb769aa3ece400', 1, 'Compute Φ = BA cos θ, with θ measured from the loop''s normal.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c9339daf05551e', 'les_bb769aa3ece400', 2, 'Derive and use the motional emf ε = BLv and the resulting magnetic drag force.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c7cd63a145f924', 'les_bb769aa3ece400', 3, 'Use Lenz''s law to find induced current directions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_16e3953ba2dab8', 'les_bb769aa3ece400', 'learn', 1, 'definition', '{"term":"Flux","body":"Magnetic flux counts the field passing through a surface: $\\Phi = BA\\cos\\theta$, where $\\theta$ is the angle between $\\vec B$ and the loop''s normal. It''s largest when the field passes straight through the loop and zero when the field lies in the loop''s plane. 1 Wb = 1 T·m²."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c9339daf05551e', 'les_bb769aa3ece400', 'learn', 2, 'worked_example', '{"title":"A 0.05 m² loop in a 0.4 T field, with B at 60° to the normal","steps":[{"latex":"\\Phi = (0.4)(0.05)\\cos 60° = 0.01\\ \\text{Wb}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c7cd63a145f924', 'les_bb769aa3ece400', 'learn', 3, 'definition', '{"term":"Motional emf","body":"A rod of length $L$ sliding at speed $v$ along rails in a field $B$ sweeps out area at rate $Lv$, so $\\varepsilon = BLv$. The induced current feels a force $F = BIL$ opposing the motion: you must push to keep it going, and that work becomes electrical energy."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7f52b683dd6b76', 'les_bb769aa3ece400', 'learn', 4, 'worked_example', '{"title":"A 0.2 m rod moves at 3 m/s through 0.5 T on rails joined by a 2 Ω resistor","steps":[{"latex":"\\varepsilon = (0.5)(0.2)(3) = 0.3\\ \\text{V}","explanation":""},{"latex":"I = \\tfrac{0.3}{2} = 0.15\\ \\text{A}","explanation":""},{"latex":"F = BIL = (0.5)(0.15)(0.2) = 0.015\\ \\text{N}","explanation":"Opposing the motion (Lenz''s law)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_215658b1022e3a', 'les_bb769aa3ece400', 'learn', 5, 'callout', '{"tone":"tip","title":"Using Lenz''s law","body":"Ask how the flux is changing. If it increases, the induced field points opposite to the applied field; if it decreases, along it. Then use the right-hand rule for loops to find the current''s direction."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a3861562edde7c', 'les_bb769aa3ece400', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Eddy-current brakes on roller coasters and trains, metal detectors, and guitar pickups all depend on changing flux."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_16e3953ba2dab8', 'les_bb769aa3ece400', 1, 'practice', 'numeric', 2, 'A 0.1 m² loop is perpendicular to a 0.3 T field. Find the flux.', '{"answer":0.03,"tolerance":0.0001,"unit":"Wb"}', '[]', '$\theta = 0$, $\cos 0 = 1$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c9339daf05551e', 'les_bb769aa3ece400', 2, 'practice', 'numeric', 2, 'A 0.5 m wing of a toy plane flies at 20 m/s through a 5 × 10⁻⁵ T vertical field. Find the emf, in mV.', '{"answer":0.5,"tolerance":0.001,"unit":"mV"}', '[]', '$BLv = 5\times10^{-5}(0.5)(20)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c7cd63a145f924', 'les_bb769aa3ece400', 3, 'practice', 'multiple_choice', 2, 'A magnet''s north pole is pushed toward a loop. The induced current makes the loop''s near face…', '{"choices":["a south pole","a north pole, repelling the magnet","neutral","alternating"],"answer":1}', '[]', 'It opposes the approach.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7f52b683dd6b76', 'les_bb769aa3ece400', 4, 'review', 'multiple_choice', 3, 'A loop is rotated until its plane is parallel to B. The flux becomes…', '{"choices":["maximum","zero","negative","unchanged"],"answer":1}', '[]', '$\cos 90° = 0$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_bb769aa3ece400', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_bb769aa3ece400', (SELECT id FROM formulas WHERE slug = 'magnetism-induction'), 1);

-- Lesson: magnetic-permeability
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_7c2c68e457c186', 'magnetic-permeability', 'Magnetic permeability', 'Classify materials as ferromagnetic, paramagnetic or diamagnetic, use permeability to describe how they change a field, and compute fields inside solenoids with and without cores.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6ba3d510933396', 'les_7c2c68e457c186', 1, 'Define permeability μ and relative permeability μ_r = μ/μ₀.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_de91dd4a8d276a', 'les_7c2c68e457c186', 2, 'Classify ferro-, para- and diamagnetic materials.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3d2c8c0b70c111', 'les_7c2c68e457c186', 3, 'Compute a solenoid''s field, B = μnI, with and without an iron core.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6ba3d510933396', 'les_7c2c68e457c186', 'learn', 1, 'definition', '{"term":"Permeability","body":"Permeability measures how a material responds to a magnetic field. In vacuum $\\mu_0 = 4\\pi\\times10^{-7}$ T·m/A. Relative permeability $\\mu_r = \\frac{\\mu}{\\mu_0}$ tells how much a material multiplies the field."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_de91dd4a8d276a', 'les_7c2c68e457c186', 'learn', 2, 'definition', '{"term":"Kinds of materials","body":"Ferromagnetic (iron, nickel, cobalt): domains of aligned atoms line up with an applied field, $\\mu_r$ in the hundreds to thousands, and they can stay magnetized. Paramagnetic (aluminum, oxygen): weakly attracted, $\\mu_r$ slightly above 1. Diamagnetic (water, copper, bismuth): weakly repelled, $\\mu_r$ slightly below 1."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3d2c8c0b70c111', 'les_7c2c68e457c186', 'learn', 3, 'definition', '{"term":"Solenoids","body":"A long coil with $n$ turns per meter carrying current $I$ has a nearly uniform field inside: $B = \\mu_0 nI$ in air, or $B = \\mu_r\\mu_0 nI$ with a core."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4537434270d000', 'les_7c2c68e457c186', 'learn', 4, 'worked_example', '{"title":"1000 turns/m carrying 2 A","steps":[{"latex":"B = (4\\pi\\times10^{-7})(1000)(2) \\approx 2.5\\times10^{-3}\\ \\text{T}","explanation":"Air core."},{"latex":"\\text{iron core}\\ (\\mu_r = 200):\\ B \\approx 0.50\\ \\text{T}","explanation":"Iron saturates near 2 T, so μ_r falls at high fields."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5a136259df0820', 'les_7c2c68e457c186', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Electromagnets in scrapyards, transformer cores and magnetic shielding all use high-permeability metals; a strong enough magnet can levitate a frog, because water is diamagnetic."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6ba3d510933396', 'les_7c2c68e457c186', 1, 'practice', 'numeric', 2, 'Find B inside an air-core solenoid with 500 turns/m and 4 A, in mT, to two decimal places.', '{"answer":2.51,"tolerance":0.01,"unit":"mT"}', '[]', '$4\pi\times10^{-7}(500)(4)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_de91dd4a8d276a', 'les_7c2c68e457c186', 2, 'practice', 'multiple_choice', 2, 'A material is weakly pushed out of a strong magnetic field. It is…', '{"choices":["ferromagnetic","paramagnetic","diamagnetic","superconducting only"],"answer":2}', '[]', 'Diamagnets are repelled.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3d2c8c0b70c111', 'les_7c2c68e457c186', 3, 'practice', 'multiple_choice', 2, 'Why does an iron nail stick to a magnet but not stay magnetized much after?', '{"choices":["Iron is diamagnetic","Its domains align in the field, then mostly randomize when removed","It''s a conductor","Gravity"],"answer":1}', '[]', 'Soft iron loses alignment easily.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4537434270d000', 'les_7c2c68e457c186', 4, 'review', 'multiple_choice', 3, 'Putting an iron core inside a solenoid…', '{"choices":["weakens the field","greatly strengthens the field","has no effect","reverses the field"],"answer":1}', '[]', '$B = \mu_r\mu_0 nI$ with large $\mu_r$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_7c2c68e457c186', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_7c2c68e457c186', (SELECT id FROM formulas WHERE slug = 'magnetism-induction'), 1);

-- Lesson: magnetic-systems
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_139a185998cfc8', 'magnetic-systems', 'Magnetic systems', 'Describe magnetic dipoles and their fields, explain why poles come in pairs, and compute the magnetic moment and torque of a current loop.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_451ca455c3da09', 'les_139a185998cfc8', 1, 'Describe magnetic dipoles, field lines and Earth''s magnetic field.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5276d31196d8c8', 'les_139a185998cfc8', 2, 'Explain why cutting a magnet never isolates a pole.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1ee1e7d7aba3cd', 'les_139a185998cfc8', 3, 'Compute a loop''s magnetic moment μ = NIA and maximum torque τ = μB.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_451ca455c3da09', 'les_139a185998cfc8', 'learn', 1, 'definition', '{"term":"Dipoles","body":"Every magnet is a dipole: field lines leave its north pole and return at its south pole, forming closed loops. No isolated pole has ever been found; cut a bar magnet and each piece has both poles. At the atomic scale, magnetism comes from electron spin and orbital motion, which are tiny current loops."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5276d31196d8c8', 'les_139a185998cfc8', 'learn', 2, 'definition', '{"term":"Earth''s field","body":"Earth''s field is about $5\\times10^{-5}$ T at the surface. Its geographic North Pole is near a magnetic south pole, which is why the north end of a compass needle points there."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1ee1e7d7aba3cd', 'les_139a185998cfc8', 'learn', 3, 'definition', '{"term":"Current loops","body":"A loop of $N$ turns, area $A$ and current $I$ is a dipole with magnetic moment $\\mu = NIA$. In a field, it feels a torque $\\tau = \\mu B\\sin\\theta$ that turns it to align with the field: the basis of motors and compasses."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c45662a0adbb28', 'les_139a185998cfc8', 'learn', 4, 'worked_example', '{"title":"A 50-turn coil of area 0.01 m² carries 2 A in a 0.2 T field","steps":[{"latex":"\\mu = 50(2)(0.01) = 1\\ \\text{A·m}^2","explanation":""},{"latex":"\\tau_{max} = (1)(0.2) = 0.2\\ \\text{N·m}","explanation":"When the coil''s plane is parallel to B."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_190e5e7e94d152', 'les_139a185998cfc8', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Electric motors, loudspeakers, hard-drive heads and MRI scanners (which align the proton dipoles in your body) all rely on dipoles in fields."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_451ca455c3da09', 'les_139a185998cfc8', 1, 'practice', 'numeric', 2, 'A 100-turn coil of area 0.002 m² carries 0.5 A. Find its magnetic moment.', '{"answer":0.1,"unit":"A·m²"}', '[]', '$100(0.5)(0.002)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5276d31196d8c8', 'les_139a185998cfc8', 2, 'practice', 'numeric', 2, 'Find that coil''s maximum torque in a 0.3 T field.', '{"answer":0.03,"tolerance":0.0001,"unit":"N·m"}', '[]', '$0.1 \times 0.3$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1ee1e7d7aba3cd', 'les_139a185998cfc8', 3, 'practice', 'multiple_choice', 2, 'A bar magnet is cut in half. Each half has…', '{"choices":["only a north pole","only a south pole","both a north and a south pole","no poles"],"answer":2}', '[]', 'Dipoles all the way down.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c45662a0adbb28', 'les_139a185998cfc8', 4, 'review', 'multiple_choice', 3, 'A current loop in a uniform field feels…', '{"choices":["a net force but no torque","a torque but no net force","neither","both"],"answer":1}', '[]', 'Forces on opposite sides cancel but don''t line up.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_139a185998cfc8', (SELECT id FROM concepts WHERE slug = 'magnetism'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_139a185998cfc8', (SELECT id FROM formulas WHERE slug = 'magnetism-induction'), 1);

-- Lesson: mass-energy-equivalence
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_24e7bfe3fcd689', 'mass-energy-equivalence', 'Mass-energy equivalence', 'Use E = mc² to relate mass and energy, compute nuclear binding energies from mass defects, and work in atomic mass units and MeV.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_10414783aeaa2a', 'les_24e7bfe3fcd689', 1, 'Use E = mc² and 1 u = 931.5 MeV/c².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1a1f48e1414e55', 'les_24e7bfe3fcd689', 2, 'Compute mass defect and binding energy for a nucleus.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_863fb6c73304c9', 'les_24e7bfe3fcd689', 3, 'Explain why binding energy per nucleon predicts fission and fusion energy.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_10414783aeaa2a', 'les_24e7bfe3fcd689', 'learn', 1, 'definition', '{"term":"Mass is energy","body":"Einstein showed that mass and energy are equivalent: $E = mc^2$. A tiny mass is a huge energy, because $c^2 = 9\\times10^{16}$ m²/s². In nuclear physics, $1\\ \\text{u} = 1.6605\\times10^{-27}$ kg $= 931.5$ MeV/$c^2$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1a1f48e1414e55', 'les_24e7bfe3fcd689', 'learn', 2, 'worked_example', '{"title":"The energy equivalent of 1 gram","steps":[{"latex":"E = (10^{-3})(3\\times10^8)^2 = 9\\times10^{13}\\ \\text{J}","explanation":"About what a large power plant produces in a day."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_863fb6c73304c9', 'les_24e7bfe3fcd689', 'learn', 3, 'definition', '{"term":"Binding energy","body":"A nucleus weighs less than its separate protons and neutrons. The difference, the mass defect $\\Delta m$, is the binding energy $\\Delta m c^2$ released when the nucleus forms. Binding energy per nucleon peaks near iron-56: fusing light nuclei or splitting heavy ones moves toward that peak and releases energy."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b0f1afe6495089', 'les_24e7bfe3fcd689', 'learn', 4, 'worked_example', '{"title":"Helium-4: 2 protons (1.007276 u), 2 neutrons (1.008665 u), nucleus 4.001506 u","steps":[{"latex":"2(1.007276) + 2(1.008665) = 4.031882\\ \\text{u}","explanation":"Total mass of the separate nucleons."},{"latex":"\\Delta m = 4.031882 - 4.001506","explanation":""},{"latex":"\\Delta m = 0.030376\\ \\text{u}","explanation":""},{"latex":"E_B = 0.030376(931.5) \\approx 28.3\\ \\text{MeV}","explanation":"About 7.1 MeV per nucleon."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9a994140ff8fe0', 'les_24e7bfe3fcd689', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"The Sun loses about 4 million tonnes of mass each second as it radiates energy; nuclear reactors convert about 0.1% of their fuel''s mass to energy."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_10414783aeaa2a', 'les_24e7bfe3fcd689', 1, 'practice', 'numeric', 2, 'How much energy is released when 0.001 u of mass converts entirely to energy? Give MeV, to two decimal places.', '{"answer":0.93,"tolerance":0.01,"unit":"MeV"}', '[]', '$0.001 \times 931.5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1a1f48e1414e55', 'les_24e7bfe3fcd689', 2, 'practice', 'numeric', 2, 'How much mass converts to give 9 × 10¹⁶ J?', '{"answer":1,"unit":"kg"}', '[]', '$\frac{E}{c^2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_863fb6c73304c9', 'les_24e7bfe3fcd689', 3, 'practice', 'multiple_choice', 2, 'A bound nucleus has ___ mass than its separate nucleons.', '{"choices":["more","less","the same","no"],"answer":1}', '[]', 'The missing mass is the binding energy.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b0f1afe6495089', 'les_24e7bfe3fcd689', 4, 'review', 'multiple_choice', 3, 'Fusing two light nuclei releases energy because the product has…', '{"choices":["less binding energy per nucleon","more binding energy per nucleon","more mass","more protons only"],"answer":1}', '[]', 'Moving toward iron''s peak releases energy.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_24e7bfe3fcd689', (SELECT id FROM concepts WHERE slug = 'modern-physics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_24e7bfe3fcd689', (SELECT id FROM formulas WHERE slug = 'modern-physics'), 1);

-- Lesson: photoelectric-effect
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_6e92c9091ef1ad', 'photoelectric-effect', 'The photoelectric effect', 'Connect blackbody radiation to quantized energy, explain the photoelectric effect with photons, compute photon energies, and use K_max = hf − φ and the threshold frequency.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a4931917271861', 'les_6e92c9091ef1ad', 4, 'Use K_max = hf − φ and find the threshold frequency.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_625a257761c971', 'les_6e92c9091ef1ad', 'learn', 6, 'worked_example', '{"title":"250 nm UV light on sodium (φ = 2.28 eV)","steps":[{"latex":"E = \\tfrac{1240\\ \\text{eV·nm}}{250\\ \\text{nm}} \\approx 4.96\\ \\text{eV}","explanation":"The shortcut hc ≈ 1240 eV·nm."},{"latex":"K_{max} = 4.96 - 2.28 \\approx 2.68\\ \\text{eV}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fbbbe22583f023', 'les_6e92c9091ef1ad', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Solar cells, camera sensors and the photomultipliers in medical scanners all rely on photons freeing electrons. Einstein''s 1921 Nobel Prize was for this explanation."}');

-- Lesson: rc-circuits
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_22c64699683be0', 'rc-circuits', 'Resistor-capacitor (RC) circuits', 'Describe how capacitors charge and discharge through resistors, use the time constant τ = RC, and analyze capacitors in steady-state circuits.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1d5899ae8530a7', 'les_22c64699683be0', 1, 'Describe charging and discharging curves and the time constant τ = RC.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_56133b189dd753', 'les_22c64699683be0', 2, 'Use V_C = V₀(1 − e^(−t/τ)) and V_C = V₀e^(−t/τ).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2ac1bbd022e4e2', 'les_22c64699683be0', 3, 'Treat an uncharged capacitor as a wire and a fully charged one as a break.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1d5899ae8530a7', 'les_22c64699683be0', 'learn', 1, 'definition', '{"term":"Charging","body":"When a switch closes, an uncharged capacitor acts like a wire and the current starts at $\\frac{V_0}{R}$. As charge builds, the capacitor''s voltage opposes the battery and the current decays: $V_C = V_0(1 - e^{-t/\\tau})$ and $I = \\frac{V_0}{R}e^{-t/\\tau}$, with time constant $\\tau = RC$. After one $\\tau$ it''s 63% charged; after $5\\tau$, essentially full, and it then acts like an open switch."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_56133b189dd753', 'les_22c64699683be0', 'learn', 2, 'definition', '{"term":"Discharging","body":"Through a resistor: $V_C = V_0 e^{-t/\\tau}$. It falls to half in $t = \\tau\\ln 2 \\approx 0.69\\tau$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ac1bbd022e4e2', 'les_22c64699683be0', 'learn', 3, 'worked_example', '{"title":"A 10 kΩ resistor, 100 μF capacitor and 9 V battery","steps":[{"latex":"\\tau = (10^4)(10^{-4}) = 1\\ \\text{s}","explanation":""},{"latex":"I_0 = \\tfrac{9}{10^4} = 0.9\\ \\text{mA}","explanation":""},{"latex":"V_C(1\\ \\text{s}) = 9(1 - e^{-1}) \\approx 5.69\\ \\text{V}","explanation":""},{"latex":"t_{99\\%} = \\tau\\ln 100 \\approx 4.6\\ \\text{s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_17bd90e3ac6e96', 'les_22c64699683be0', 'experiment', 4, 'activity', '{"activity":"rc-circuit","title":"Charge and discharge a capacitor","params":{"mode":"charge","voltage":9,"resistance":10,"capacitance":100}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_527d49995eea46', 'les_22c64699683be0', 'experiment', 5, 'callout', '{"tone":"tip","title":"Try this","body":"Double R and see the curve stretch: τ doubles. Switch to discharging and find the time when the voltage reaches 4.5 V."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_575610a39ed0ad', 'les_22c64699683be0', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Windshield-wiper delays, camera flashes, pacemakers and the blinking of LEDs are all timed by RC circuits."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1d5899ae8530a7', 'les_22c64699683be0', 1, 'practice', 'numeric', 2, 'Find τ for 2 kΩ and 50 μF.', '{"answer":0.1,"unit":"s"}', '[]', '$2000 \times 5\times10^{-5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_56133b189dd753', 'les_22c64699683be0', 2, 'practice', 'numeric', 2, 'A capacitor discharging with τ = 2 s starts at 10 V. Find V after 2 s, to two decimal places.', '{"answer":3.68,"tolerance":0.01,"unit":"V"}', '[]', '$10e^{-1}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2ac1bbd022e4e2', 'les_22c64699683be0', 3, 'practice', 'multiple_choice', 2, 'Long after the switch closes in a charging RC circuit, the current is…', '{"choices":["V₀/R","zero","maximum","V₀/(RC)"],"answer":1}', '[]', 'A full capacitor blocks steady current.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_17bd90e3ac6e96', 'les_22c64699683be0', 4, 'review', 'multiple_choice', 3, 'Right after the switch closes, the voltage across the uncharged capacitor is…', '{"choices":["V₀","zero","V₀/2","infinite"],"answer":1}', '[]', 'It has no charge yet, so $V = \frac{Q}{C} = 0$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_22c64699683be0', (SELECT id FROM concepts WHERE slug = 'circuits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_22c64699683be0', (SELECT id FROM formulas WHERE slug = 'dc-circuits'), 1);

-- Lesson: simple-circuits-emf
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ad2023586e1258', 'simple-circuits-emf', 'Simple circuits', 'Read circuit diagrams, place meters correctly, and account for a real battery''s internal resistance with terminal voltage V = ε − Ir.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_280f345b2e5bb5', 'les_ad2023586e1258', 1, 'Interpret circuit symbols and tell open circuits from closed and short circuits.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9ba17a70139489', 'les_ad2023586e1258', 2, 'Connect ammeters in series and voltmeters in parallel.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_4c928a9adc37f3', 'les_ad2023586e1258', 3, 'Use emf and internal resistance: I = ε/(R + r) and V_T = ε − Ir.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_280f345b2e5bb5', 'les_ad2023586e1258', 'learn', 1, 'definition', '{"term":"Circuits","body":"Current flows only around a closed loop. An open circuit has a break, so no current flows; a short circuit gives current a path with almost no resistance, so a large current flows. Ideal ammeters have zero resistance and go in series; ideal voltmeters have infinite resistance and go in parallel across the element they measure."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9ba17a70139489', 'les_ad2023586e1258', 'learn', 2, 'definition', '{"term":"Real batteries","body":"A battery''s emf $\\varepsilon$ is the energy it gives each coulomb. It also has internal resistance $r$, so the current is $I = \\frac{\\varepsilon}{R + r}$ and the voltage at its terminals is $V_T = \\varepsilon - Ir$, which falls as the current rises."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_4c928a9adc37f3', 'les_ad2023586e1258', 'learn', 3, 'worked_example', '{"title":"A 12 V battery with r = 0.5 Ω drives a 5.5 Ω load","steps":[{"latex":"I = \\tfrac{12}{5.5 + 0.5} = 2\\ \\text{A}","explanation":""},{"latex":"V_T = 12 - 2(0.5) = 11\\ \\text{V}","explanation":""},{"latex":"\\text{shorted: } I = \\tfrac{12}{0.5} = 24\\ \\text{A}","explanation":"Dangerous: the battery heats rapidly."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ec9303af26bece', 'les_ad2023586e1258', 'experiment', 4, 'activity', '{"activity":"circuit-builder","title":"Measure currents and voltages"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d2ad2dca71ae7a', 'les_ad2023586e1258', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Car headlights dim while the starter motor runs: the large current makes $Ir$ large, so the terminal voltage drops. Fuses protect against short circuits."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_280f345b2e5bb5', 'les_ad2023586e1258', 1, 'practice', 'numeric', 2, 'A 9 V battery reads 8.4 V while delivering 0.3 A. Find its internal resistance.', '{"answer":2,"unit":"Ω"}', '[]', '$r = \frac{9 - 8.4}{0.3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9ba17a70139489', 'les_ad2023586e1258', 2, 'practice', 'numeric', 2, 'A 6 V battery with r = 1 Ω powers a 2 Ω resistor. Find the current.', '{"answer":2,"unit":"A"}', '[]', '$\frac{6}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_4c928a9adc37f3', 'les_ad2023586e1258', 3, 'practice', 'multiple_choice', 2, 'A voltmeter accidentally connected in series with a bulb causes…', '{"choices":["the bulb to burn brighter","almost no current, so the bulb goes out","a short circuit","no change"],"answer":1}', '[]', 'Its huge resistance blocks current.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ec9303af26bece', 'les_ad2023586e1258', 4, 'review', 'multiple_choice', 3, 'When does a battery''s terminal voltage equal its emf?', '{"choices":["when shorted","when no current flows","always","when the load is small"],"answer":1}', '[]', '$V_T = \varepsilon - Ir$ with $I = 0$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ad2023586e1258', (SELECT id FROM concepts WHERE slug = 'circuits'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_ad2023586e1258', (SELECT id FROM formulas WHERE slug = 'dc-circuits'), 1);

-- Lesson: snells-law-refraction
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_8b0ffb6fcd3a38', 'snells-law-refraction', 'Refraction', 'Apply Snell''s law between any two media, find speeds and wavelengths in materials, explain apparent depth and dispersion, and compute critical angles.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6c71af87bd6485', 'les_8b0ffb6fcd3a38', 1, 'Use n = c/v and n₁ sin θ₁ = n₂ sin θ₂ between any two media.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_82d2fa024808c9', 'les_8b0ffb6fcd3a38', 2, 'Explain why frequency stays fixed while wavelength changes: λ_n = λ/n.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7806a39dea4b5a', 'les_8b0ffb6fcd3a38', 3, 'Compute apparent depth and critical angles, and explain dispersion.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6c71af87bd6485', 'les_8b0ffb6fcd3a38', 'learn', 1, 'definition', '{"term":"Speed and wavelength","body":"In a medium of index $n$, light travels at $v = \\frac{c}{n}$: in glass ($n = 1.5$), $2\\times10^8$ m/s. Its frequency is set by the source and doesn''t change, so the wavelength shrinks to $\\lambda_n = \\frac{\\lambda}{n}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_82d2fa024808c9', 'les_8b0ffb6fcd3a38', 'learn', 2, 'worked_example', '{"title":"Light passes from glass (n = 1.50) into water (n = 1.33) at 40°","steps":[{"latex":"\\sin\\theta_2 = \\tfrac{1.50\\sin 40°}{1.33} \\approx 0.725","explanation":""},{"latex":"\\theta_2 \\approx 46.5°","explanation":"Bent away from the normal: water has the lower index."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7806a39dea4b5a', 'les_8b0ffb6fcd3a38', 'learn', 3, 'definition', '{"term":"Apparent depth","body":"Looking straight down into water, objects appear at depth $d'' \\approx \\frac{d}{n}$: a 2 m pool looks about 1.5 m deep."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_537a69513409f1', 'les_8b0ffb6fcd3a38', 'learn', 4, 'definition', '{"term":"Dispersion and total internal reflection","body":"$n$ depends slightly on wavelength (violet bends most), so prisms and raindrops split white light. Going to a lower index, beyond $\\theta_c = \\sin^{-1}\\frac{n_2}{n_1}$ all the light reflects; diamond ($n = 2.42$) has $\\theta_c \\approx 24.4°$, which traps light and makes it sparkle."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a7d900cc6aeaf4', 'les_8b0ffb6fcd3a38', 'experiment', 5, 'activity', '{"activity":"ray-optics","title":"Refraction in a lens","params":{"optic":"converging","focal":10,"object":25}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bbfd1f16ac27ef', 'les_8b0ffb6fcd3a38', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Rainbows, mirages, fiber optics and the shimmer above hot roads all come from refraction."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6c71af87bd6485', 'les_8b0ffb6fcd3a38', 1, 'practice', 'numeric', 1, 'Find the speed of light in water (n = 1.33), in units of $10^8$ m/s, to two decimal places.', '{"answer":2.26,"tolerance":0.01}', '[]', '$\frac{3}{1.33}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_82d2fa024808c9', 'les_8b0ffb6fcd3a38', 2, 'practice', 'numeric', 2, '633 nm laser light enters glass (n = 1.5). Find its wavelength inside, in nm.', '{"answer":422,"unit":"nm"}', '[]', '$\frac{633}{1.5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7806a39dea4b5a', 'les_8b0ffb6fcd3a38', 3, 'practice', 'multiple_choice', 2, 'When light enters glass from air, which stays the same?', '{"choices":["speed","wavelength","frequency","direction"],"answer":2}', '[]', 'The source sets the frequency.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_537a69513409f1', 'les_8b0ffb6fcd3a38', 4, 'review', 'multiple_choice', 3, 'Total internal reflection can happen when light goes from…', '{"choices":["air to water","water to glass","glass to air","any medium to any medium"],"answer":2}', '[]', 'It needs a move to a lower index.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_8b0ffb6fcd3a38', (SELECT id FROM concepts WHERE slug = 'optics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_8b0ffb6fcd3a38', (SELECT id FROM formulas WHERE slug = 'optics-equations'), 1);

-- Lesson: thermal-conductivity
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_daf040561d76a3', 'thermal-conductivity', 'Specific heat and thermal conductivity', 'Connect specific heat to how fast temperatures change, and compute the rate of heat conduction through materials with P = kAΔT/L.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_19d582ced79076', 'les_daf040561d76a3', 1, 'Use Q = mcΔT to compare how materials warm.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5b9d5ff05801b4', 'les_daf040561d76a3', 2, 'Compute conduction rates with P = kAΔT/L.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3b81fc0de09cb4', 'les_daf040561d76a3', 3, 'Explain how thickness, area and material control heat loss.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_19d582ced79076', 'les_daf040561d76a3', 'learn', 1, 'definition', '{"term":"Specific heat, revisited","body":"For the same heat input, a material with low specific heat changes temperature quickly: 1 kJ warms 1 kg of copper ($c = 385$) by 2.6 °C but 1 kg of water ($c = 4186$) by only 0.24 °C."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5b9d5ff05801b4', 'les_daf040561d76a3', 'learn', 2, 'definition', '{"term":"Conduction rate","body":"Heat conducts through a slab at rate $P = \\frac{Q}{\\Delta t} = \\frac{kA\\Delta T}{L}$, where $k$ is the thermal conductivity (W/(m·K)), $A$ the area, $L$ the thickness and $\\Delta T$ the temperature difference. Copper $k \\approx 400$, glass 0.8, wood 0.1, fiberglass 0.04, still air 0.025."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3b81fc0de09cb4', 'les_daf040561d76a3', 'learn', 3, 'worked_example', '{"title":"A 1 m² single-pane window, 4 mm thick, 20 °C warmer inside","steps":[{"latex":"P = \\tfrac{(0.8)(1)(20)}{0.004} = 4000\\ \\text{W}","explanation":"Real windows lose less, because still air layers on each surface add insulation."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e99913b97c3992', 'les_daf040561d76a3', 'learn', 4, 'worked_example', '{"title":"10 m² of 10 cm fiberglass with the same 20 °C difference","steps":[{"latex":"P = \\tfrac{(0.04)(10)(20)}{0.1} = 80\\ \\text{W}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3e07aba3a005ed', 'les_daf040561d76a3', 'learn', 5, 'callout', '{"tone":"note","title":"Feeling temperature","body":"Metal feels colder than wood at the same temperature because its high $k$ draws heat from your skin faster."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_27a87abef06081', 'les_daf040561d76a3', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Double-pane windows trap a gas layer, cooking pans pair a copper base with a wooden handle, and insulation is sold by R-value, which is proportional to $\\frac{L}{k}$."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_19d582ced79076', 'les_daf040561d76a3', 1, 'practice', 'numeric', 2, 'A copper rod (k = 400) of cross-section 1 cm² and length 0.5 m has ends 100 °C apart. Find the heat flow.', '{"answer":8,"unit":"W"}', '[]', '$\frac{400(10^{-4})(100)}{0.5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5b9d5ff05801b4', 'les_daf040561d76a3', 2, 'practice', 'multiple_choice', 2, 'Doubling a wall''s thickness changes the heat loss by a factor of…', '{"choices":["2","½","4","1"],"answer":1}', '[]', '$P \propto \frac{1}{L}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3b81fc0de09cb4', 'les_daf040561d76a3', 3, 'practice', 'numeric', 2, 'How much heat warms 0.2 kg of copper by 50 °C?', '{"answer":3850,"unit":"J"}', '[]', '$0.2(385)(50)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e99913b97c3992', 'les_daf040561d76a3', 4, 'review', 'multiple_choice', 3, 'Why does a puffy jacket keep you warm?', '{"choices":["It generates heat","It traps still air, which conducts poorly","Feathers are hot","It reflects all radiation"],"answer":1}', '[]', 'Air''s $k$ is tiny if it can''t circulate.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_daf040561d76a3', (SELECT id FROM concepts WHERE slug = 'thermal-physics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_daf040561d76a3', (SELECT id FROM formulas WHERE slug = 'heat-thermodynamics'), 1);

-- Lesson: thin-film-interference
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_f010a8089867c8', 'thin-film-interference', 'Thin-film interference', 'Explain the colors of soap bubbles and oil slicks, account for phase shifts on reflection, and design anti-reflective coatings.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8ab734fa38eb3c', 'les_f010a8089867c8', 1, 'Identify phase shifts when light reflects from a higher-index medium.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_91739d04d1fcfd', 'les_f010a8089867c8', 2, 'Find constructive and destructive conditions for thin films.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f48f724b05639c', 'les_f010a8089867c8', 3, 'Compute anti-reflective coating thickness, t = λ/(4n).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8ab734fa38eb3c', 'les_f010a8089867c8', 'learn', 1, 'definition', '{"term":"Two reflections","body":"Light reflects from both the top and bottom surfaces of a thin film. The bottom ray travels an extra $2t$ inside the film, where the wavelength is $\\frac{\\lambda}{n}$. Each reflection off a higher-index medium adds a half-wavelength shift."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_91739d04d1fcfd', 'les_f010a8089867c8', 'learn', 2, 'definition', '{"term":"Conditions (near-normal incidence)","body":"If exactly one reflection is shifted (a soap film in air): constructive when $2nt = (m + \\frac12)\\lambda$, destructive when $2nt = m\\lambda$. If both or neither are shifted (oil on water, coatings on glass): swap the two conditions."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f48f724b05639c', 'les_f010a8089867c8', 'learn', 3, 'worked_example', '{"title":"A soap film (n = 1.33), 100 nm thick, in air","steps":[{"latex":"2nt = (m + \\tfrac12)\\lambda \\Rightarrow \\lambda = \\tfrac{4nt}{2m + 1}","explanation":"Only the top reflection is shifted."},{"latex":"m = 0:\\ \\lambda = 4(1.33)(100) = 532\\ \\text{nm}","explanation":"The film looks green."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9c542a3797861d', 'les_f010a8089867c8', 'learn', 4, 'worked_example', '{"title":"An anti-reflective coating (n = 1.38) on glass (n = 1.5) for 550 nm","steps":[{"latex":"2nt = \\tfrac{\\lambda}{2} \\Rightarrow t = \\tfrac{\\lambda}{4n}","explanation":"Both reflections are shifted; we want destructive interference."},{"latex":"t = \\tfrac{550}{4(1.38)} \\approx 99.6\\ \\text{nm}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e9845fd0f284f0', 'les_f010a8089867c8', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Camera lenses and eyeglasses use anti-reflective coatings; peacock feathers, butterfly wings and oil slicks get their shimmering colors from thin layers."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8ab734fa38eb3c', 'les_f010a8089867c8', 1, 'practice', 'numeric', 2, 'Find the thinnest coating (n = 1.25) on glass that cancels reflected 600 nm light.', '{"answer":120,"unit":"nm"}', '[]', '$\frac{600}{4(1.25)}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_91739d04d1fcfd', 'les_f010a8089867c8', 2, 'practice', 'numeric', 3, 'A soap film (n = 1.33) in air strongly reflects 665 nm light at its thinnest. Find its thickness, to the nearest nm.', '{"answer":125,"tolerance":1,"unit":"nm"}', '[]', '$t = \frac{\lambda}{4n} = \frac{665}{5.32}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f48f724b05639c', 'les_f010a8089867c8', 3, 'practice', 'multiple_choice', 2, 'A soap film gets so thin (t ≪ λ) that it looks black just before popping. Why?', '{"choices":["It absorbs light","The single phase shift makes the two reflections cancel","It''s too thin to reflect","It turns opaque"],"answer":1}', '[]', 'With $t \to 0$, only the half-wavelength shift remains: destructive.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9c542a3797861d', 'les_f010a8089867c8', 4, 'review', 'multiple_choice', 3, 'Oil (n = 1.45) floats on water (n = 1.33). How many reflections get a phase shift?', '{"choices":["0","1","2","3"],"answer":1}', '[]', 'Only the top (air to oil); oil to water goes to a lower index.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_f010a8089867c8', (SELECT id FROM concepts WHERE slug = 'waves'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_f010a8089867c8', (SELECT id FROM formulas WHERE slug = 'interference'), 1);

-- Lesson: torque-work-power
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_0f6eccc474b242', 'torque-work-power', 'Torque and work', 'Compute the work done by torques (constant or varying), read torque–angle graphs, relate rotational power to torque and angular speed, and follow energy transfer in rotating systems.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_cc414b4aa99e34', 'les_0f6eccc474b242', 1, 'Compute work by a constant torque, W = τΔθ, and by a varying torque as the area under a τ–θ graph.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_64b9eb91fb0b0c', 'les_0f6eccc474b242', 2, 'Use rotational power P = τω.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_df0da16ee512f7', 'les_0f6eccc474b242', 3, 'Apply the work–energy theorem to rotating systems, including friction torques.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cc414b4aa99e34', 'les_0f6eccc474b242', 'learn', 1, 'definition', '{"term":"Work by a torque","body":"A force applied at radius $r$ moves its point of application through an arc $s = r\\Delta\\theta$, so the work is $W = Fr\\Delta\\theta = \\tau\\Delta\\theta$ ($\\Delta\\theta$ in radians). If the torque varies, the work is the area under the torque–angle graph. A torque opposite the rotation, such as friction, does negative work."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_64b9eb91fb0b0c', 'les_0f6eccc474b242', 'learn', 2, 'worked_example', '{"title":"Torque rises steadily from 0 to 4 N·m over the first 2 rad, then stays at 4 N·m for 3 more rad","steps":[{"latex":"W_1 = \\tfrac12(2)(4) = 4\\ \\text{J}","explanation":"Triangle under the graph."},{"latex":"W_2 = 4(3) = 12\\ \\text{J}","explanation":"Rectangle."},{"latex":"W = 16\\ \\text{J}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_df0da16ee512f7', 'les_0f6eccc474b242', 'learn', 3, 'worked_example', '{"title":"Pushing a door: 10 N at 0.8 m from the hinge, always perpendicular, through 90°","steps":[{"latex":"W = \\tau\\Delta\\theta = (10)(0.8)\\left(\\tfrac{\\pi}{2}\\right) \\approx 12.6\\ \\text{J}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f8ffe7232aac91', 'les_0f6eccc474b242', 'learn', 4, 'definition', '{"term":"Power and energy transfer","body":"Rotational power is $P = \\tau\\omega$. By the work–energy theorem, $W_{net} = \\Delta K_{rot}$: the net work of all torques changes the rotational kinetic energy, and friction torques turn it into thermal energy."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5405a01f1c09ab', 'les_0f6eccc474b242', 'learn', 5, 'worked_example', '{"title":"A wheel with 50 J of rotational kinetic energy is stopped by a 2 N·m friction torque","steps":[{"latex":"-\\tau\\Delta\\theta = -50\\ \\text{J} \\Rightarrow \\Delta\\theta = 25\\ \\text{rad}","explanation":""},{"latex":"\\tfrac{25}{2\\pi} \\approx 4.0\\ \\text{revolutions}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_677339e739e56a', 'les_0f6eccc474b242', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engine and motor ratings give torque and rpm, and power is their product: a drill delivering 0.5 N·m at 300 rad/s supplies 150 W."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_cc414b4aa99e34', 'les_0f6eccc474b242', 1, 'practice', 'numeric', 2, 'A motor exerts 0.5 N·m at 300 rad/s. Find its power.', '{"answer":150,"unit":"W"}', '[]', '$P = \tau\omega$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_64b9eb91fb0b0c', 'les_0f6eccc474b242', 2, 'practice', 'numeric', 2, 'A 3 N·m torque turns a wheel through 4 revolutions. Find the work, to the nearest joule.', '{"answer":75,"tolerance":0.5,"unit":"J"}', '[]', '$3 \times 8\pi \approx 75.4$ J.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_df0da16ee512f7', 'les_0f6eccc474b242', 3, 'practice', 'numeric', 3, 'A flywheel (I = 2 kg·m²) at 20 rad/s is stopped by a constant friction torque in 10 revolutions. Find the torque''s size, to two decimal places.', '{"answer":6.37,"tolerance":0.02,"unit":"N·m"}', '[]', '$K = 400$ J; $\tau = \frac{400}{20\pi} \approx 6.37$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f8ffe7232aac91', 'les_0f6eccc474b242', 4, 'review', 'multiple_choice', 3, 'A τ–θ graph is a horizontal line at 5 N·m from 0 to 6 rad. The work done is…', '{"choices":["5 J","30 J","11 J","1.2 J"],"answer":1}', '[]', 'Area: $5 \times 6$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_0f6eccc474b242', (SELECT id FROM concepts WHERE slug = 'rotation'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_0f6eccc474b242', (SELECT id FROM formulas WHERE slug = 'rotational-dynamics'), 1);

-- Lesson: types-radioactive-decay
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_412b6e6ee36df8', 'types-radioactive-decay', 'Types of radioactive decay', 'Write equations for alpha, beta-minus, beta-plus, electron capture and gamma decay, using conservation of charge, nucleon number and energy, and trace decay series.', 35, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2b4971a4b654fa', 'les_412b6e6ee36df8', 1, 'Write nuclear equations for α, β⁻, β⁺, electron capture and γ decay.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_06480bf8f9ba51', 'les_412b6e6ee36df8', 2, 'Apply conservation of charge, nucleon number and energy to decays.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a5b97249ffa23f', 'les_412b6e6ee36df8', 3, 'Count the decays in a decay series.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2b4971a4b654fa', 'les_412b6e6ee36df8', 'learn', 1, 'definition', '{"term":"Decay types","body":"Alpha ($^4_2$He): A − 4, Z − 2. Beta-minus: a neutron becomes a proton, emitting an electron and an antineutrino; Z + 1. Beta-plus: a proton becomes a neutron, emitting a positron and a neutrino; Z − 1. Electron capture: the nucleus absorbs an inner electron; Z − 1. Gamma: an excited nucleus emits a photon, with no change in A or Z."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_06480bf8f9ba51', 'les_412b6e6ee36df8', 'learn', 2, 'worked_example', '{"title":"Fluorine-18 (used in PET scans) decays by positron emission","steps":[{"latex":"^{18}_{9}\\text{F} \\to\\, ^{18}_{8}\\text{O} + ^{0}_{+1}e + \\nu","explanation":"Top and bottom numbers balance."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a5b97249ffa23f', 'les_412b6e6ee36df8', 'learn', 3, 'worked_example', '{"title":"Uranium-238 decays through a series to lead-206. How many α and β⁻ decays?","steps":[{"latex":"\\Delta A = 238 - 206 = 32 \\Rightarrow 8\\ \\alpha","explanation":"Only alpha decay changes A."},{"latex":"Z: 92 - 2(8) = 76;\\ 82 - 76 = 6\\ \\beta^-","explanation":"Each β⁻ raises Z by 1."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f613600ce8653e', 'les_412b6e6ee36df8', 'learn', 4, 'callout', '{"tone":"note","title":"Why neutrinos?","body":"In beta decay, electrons come out with a range of energies, not one value. Pauli proposed an unseen particle carrying the missing energy: the neutrino, detected in 1956."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c8fba19adfd5d4', 'les_412b6e6ee36df8', 'experiment', 5, 'activity', '{"activity":"half-life","title":"Random decay, predictable half-life","params":{"halfLife":5}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_961e9288c301f2', 'les_412b6e6ee36df8', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"PET scans detect the gamma rays from positron–electron annihilation, and smoke detectors use americium-241, an alpha emitter."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2b4971a4b654fa', 'les_412b6e6ee36df8', 1, 'practice', 'numeric', 2, 'Thorium-232 (Z = 90) decays to lead-208 (Z = 82). How many alpha decays occur?', '{"answer":6}', '[]', '$\frac{232 - 208}{4}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_06480bf8f9ba51', 'les_412b6e6ee36df8', 2, 'practice', 'numeric', 3, 'How many beta-minus decays in that series?', '{"answer":4}', '[]', '$90 - 12 = 78$, and $82 - 78 = 4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a5b97249ffa23f', 'les_412b6e6ee36df8', 3, 'practice', 'multiple_choice', 2, 'Which decay leaves both A and Z unchanged?', '{"choices":["alpha","beta-minus","beta-plus","gamma"],"answer":3}', '[]', 'A gamma ray is just a photon.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f613600ce8653e', 'les_412b6e6ee36df8', 4, 'review', 'multiple_choice', 3, 'Cobalt-60 (Z = 27) undergoes β⁻ decay. The product is…', '{"choices":["iron-60 (Z = 26)","nickel-60 (Z = 28)","cobalt-59","manganese-56"],"answer":1}', '[]', 'Z + 1, same A.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_412b6e6ee36df8', (SELECT id FROM concepts WHERE slug = 'modern-physics'));

-- Lesson: wave-particle-duality
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a7ae6dddd2c21d', 'wave-particle-duality', 'Quantum theory and wave-particle duality', 'See how light shows particle behavior and matter shows wave behavior, compute de Broglie wavelengths, and explain electron diffraction.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_424ce8105cf407', 'les_a7ae6dddd2c21d', 1, 'Describe evidence that light acts as both a wave and a particle.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6aeac95ef78331', 'les_a7ae6dddd2c21d', 2, 'Compute de Broglie wavelengths, λ = h/p, and photon momentum p = h/λ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f0b6ad5acdcff2', 'les_a7ae6dddd2c21d', 3, 'Explain why wave behavior shows up for electrons but not baseballs.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_424ce8105cf407', 'les_a7ae6dddd2c21d', 'learn', 1, 'definition', '{"term":"Duality","body":"Light interferes and diffracts like a wave, but in the photoelectric effect and Compton scattering it delivers energy in packets, like particles. In 1924 de Broglie proposed that matter does the reverse: a particle with momentum $p$ has wavelength $\\lambda = \\frac{h}{p}$. Photons carry momentum too: $p = \\frac{h}{\\lambda}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6aeac95ef78331', 'les_a7ae6dddd2c21d', 'learn', 2, 'worked_example', '{"title":"An electron at 1 × 10⁶ m/s and a baseball (0.145 kg) at 40 m/s","steps":[{"latex":"\\lambda_e = \\tfrac{6.626\\times10^{-34}}{(9.11\\times10^{-31})(10^6)}","explanation":""},{"latex":"\\lambda_e \\approx 7.3\\times10^{-10}\\ \\text{m}","explanation":"Comparable to atomic spacing, so crystals diffract electrons."},{"latex":"\\lambda_{ball} = \\tfrac{6.626\\times10^{-34}}{(0.145)(40)}","explanation":""},{"latex":"\\lambda_{ball} \\approx 1.1\\times10^{-34}\\ \\text{m}","explanation":"Unmeasurably small."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f0b6ad5acdcff2', 'les_a7ae6dddd2c21d', 'learn', 3, 'definition', '{"term":"Evidence","body":"In 1927 Davisson and Germer saw electrons diffract off a nickel crystal, exactly as de Broglie predicted. Fired one at a time through two slits, electrons still build up an interference pattern: each one''s arrival point is random, but the probabilities follow the wave."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f8131d09f39697', 'les_a7ae6dddd2c21d', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Electron microscopes resolve detail far finer than light microscopes because electrons'' wavelengths are thousands of times shorter than visible light''s."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_424ce8105cf407', 'les_a7ae6dddd2c21d', 1, 'practice', 'numeric', 2, 'Find the momentum of a 500 nm photon, in units of $10^{-27}$ kg·m/s, to two decimal places.', '{"answer":1.33,"tolerance":0.01}', '[]', '$\frac{6.626\times10^{-34}}{5\times10^{-7}}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6aeac95ef78331', 'les_a7ae6dddd2c21d', 2, 'practice', 'numeric', 3, 'Find the de Broglie wavelength of a proton at 1 × 10⁴ m/s, in nm, to two decimal places.', '{"answer":0.04,"tolerance":0.001,"unit":"nm"}', '[]', '$\frac{6.626\times10^{-34}}{1.67\times10^{-27}(10^4)} \approx 3.97\times10^{-11}$ m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f0b6ad5acdcff2', 'les_a7ae6dddd2c21d', 3, 'practice', 'multiple_choice', 2, 'If an electron''s speed doubles, its de Broglie wavelength…', '{"choices":["doubles","halves","stays the same","quadruples"],"answer":1}', '[]', '$\lambda \propto \frac{1}{p}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f8131d09f39697', 'les_a7ae6dddd2c21d', 4, 'review', 'multiple_choice', 3, 'Which experiment showed the wave nature of electrons?', '{"choices":["photoelectric effect","Davisson–Germer electron diffraction","Rutherford scattering","Millikan oil drop"],"answer":1}', '[]', 'Diffraction is wave behavior.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a7ae6dddd2c21d', (SELECT id FROM concepts WHERE slug = 'modern-physics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a7ae6dddd2c21d', (SELECT id FROM formulas WHERE slug = 'modern-physics'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a7ae6dddd2c21d', (SELECT id FROM formulas WHERE slug = 'photon-energy'), 2);

-- Lesson: wave-pulses
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_bb4685ae565169', 'wave-pulses', 'Properties of wave pulses and waves', 'Describe pulses on strings, find wave speed from tension and linear density, and apply superposition to overlapping pulses.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b17ab8b9d583b0', 'les_bb4685ae565169', 1, 'Describe a pulse as a disturbance carrying energy without carrying the medium.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3b4f3fd424a885', 'les_bb4685ae565169', 2, 'Use v = √(F_T/μ) for waves on a string.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_84f5cf0f48b1d9', 'les_bb4685ae565169', 3, 'Apply superposition: overlapping pulses add, then pass through each other unchanged.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b17ab8b9d583b0', 'les_bb4685ae565169', 'learn', 1, 'definition', '{"term":"Pulses","body":"A single flick of a rope sends a pulse along it: each bit of rope moves up and back down, but the shape travels. A periodic wave is a regular train of pulses."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3b4f3fd424a885', 'les_bb4685ae565169', 'learn', 2, 'definition', '{"term":"Speed on a string","body":"The medium sets the speed: on a string under tension $F_T$ with mass per length $\\mu$, $v = \\sqrt{\\frac{F_T}{\\mu}}$. Tighter and lighter strings carry faster waves."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_84f5cf0f48b1d9', 'les_bb4685ae565169', 'learn', 3, 'worked_example', '{"title":"A string with μ = 0.01 kg/m under 100 N of tension","steps":[{"latex":"v = \\sqrt{\\tfrac{100}{0.01}} = 100\\ \\text{m/s}","explanation":""},{"latex":"\\text{4× tension: } v = 200\\ \\text{m/s}","explanation":"Speed scales as the square root of tension."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ff18fef6a77231', 'les_bb4685ae565169', 'learn', 4, 'definition', '{"term":"Superposition","body":"When pulses overlap, the displacements add. Two upward pulses add to a taller one (constructive); an upward and a downward pulse of equal size cancel for an instant (destructive). Then each continues unchanged, as if the other weren''t there."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_44fd4d69d4e93a', 'les_bb4685ae565169', 'experiment', 5, 'activity', '{"activity":"waves","title":"Add two waves","params":{"mode":"superpose","phase":180}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c43377b608c31c', 'les_bb4685ae565169', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Guitar strings are tuned by tension, noise-cancelling headphones use destructive superposition, and seismologists time pulses through Earth to map its interior."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b17ab8b9d583b0', 'les_bb4685ae565169', 1, 'practice', 'numeric', 2, 'A 0.5 m string has a mass of 0.005 kg and tension 40 N. Find the wave speed.', '{"answer":63.2,"tolerance":0.1,"unit":"m/s"}', '[]', '$\mu = 0.01$ kg/m; $\sqrt{4000}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3b4f3fd424a885', 'les_bb4685ae565169', 2, 'practice', 'numeric', 2, 'Pulses of +3 cm and −1 cm overlap. Find the combined displacement.', '{"answer":2,"unit":"cm"}', '[]', '$3 + (-1)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_84f5cf0f48b1d9', 'les_bb4685ae565169', 3, 'practice', 'multiple_choice', 2, 'To double a string''s wave speed, the tension must be…', '{"choices":["doubled","quadrupled","halved","squared"],"answer":1}', '[]', '$v \propto \sqrt{F_T}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ff18fef6a77231', 'les_bb4685ae565169', 4, 'review', 'multiple_choice', 3, 'After two equal and opposite pulses momentarily cancel, they…', '{"choices":["vanish permanently","continue on unchanged","reflect","merge into one"],"answer":1}', '[]', 'The energy is still there, stored as the string''s motion.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_bb4685ae565169', (SELECT id FROM concepts WHERE slug = 'waves'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_bb4685ae565169', (SELECT id FROM formulas WHERE slug = 'wave-speed'), 1);

