-- Corrections to rows that already shipped (skipped if edited since)
UPDATE lesson_objectives SET text = 'Describe blackbody radiation and use Wien''s law, λ_max T = 2.898 × 10⁻³ m·K.' WHERE id = 'lobj_0d098520dfff94' AND text = 'Describe the photoelectric experiment and why the wave model fails to explain it.';
UPDATE lesson_objectives SET text = 'Describe the photoelectric experiment and why the wave model fails to explain it.' WHERE id = 'lobj_168b64642b00c1' AND text = 'Compute photon energy E = hf = hc/λ in joules and electron-volts.';
UPDATE lesson_objectives SET text = 'Compute photon energy E = hf = hc/λ in joules and electron-volts.' WHERE id = 'lobj_bad567eb9a9e44' AND text = 'Use K_max = hf − φ and find the threshold frequency.';
UPDATE lesson_blocks SET data = '{"term":"Blackbody radiation","body":"Every object glows with a spectrum set by its temperature. A hotter object emits more in total and peaks at a shorter wavelength: Wien''s law $\\lambda_{max}T = 2.898\\times10^{-3}$ m·K. Classical physics predicted infinite ultraviolet emission; Planck fixed it in 1900 by assuming energy comes in packets $E = hf$, the start of quantum physics."}' WHERE id = 'blk_0d098520dfff94' AND data = '{"term":"The puzzle","body":"Light shining on a metal can eject electrons. Experiments showed that below a threshold frequency no electrons come out, however bright the light; above it, electrons emerge instantly; and brighter light ejects more electrons, but not faster ones. Waves can''t explain this."}';
UPDATE lesson_blocks SET kind = 'worked_example', data = '{"title":"Peak wavelengths of the Sun (5800 K) and a person (310 K)","steps":[{"latex":"\\lambda_{Sun} = \\tfrac{2.898\\times10^{-3}}{5800} \\approx 500\\ \\text{nm}","explanation":"Visible light."},{"latex":"\\lambda_{person} = \\tfrac{2.898\\times10^{-3}}{310} \\approx 9.3\\ \\mu\\text{m}","explanation":"Infrared, which is why thermal cameras see people in the dark."}]}' WHERE id = 'blk_168b64642b00c1' AND kind = 'definition' AND data = '{"term":"Einstein''s photons","body":"Light comes in packets (photons) of energy $E = hf$, with $h = 6.626\\times10^{-34}$ J·s. One photon gives its energy to one electron, which needs at least the work function $\\phi$ to escape: $K_{max} = hf - \\phi$. 1 eV $= 1.602\\times10^{-19}$ J."}';
UPDATE lesson_blocks SET kind = 'definition', data = '{"term":"The puzzle","body":"Light shining on a metal can eject electrons. Experiments showed that below a threshold frequency no electrons come out, however bright the light; above it, electrons emerge instantly; and brighter light ejects more electrons, but not faster ones. Waves can''t explain this."}' WHERE id = 'blk_bad567eb9a9e44' AND kind = 'worked_example' AND data = '{"title":"Energy of a 500 nm (green) photon","steps":[{"latex":"E = \\tfrac{hc}{\\lambda}","explanation":""},{"latex":"E = \\tfrac{(6.626\\times10^{-34})(3\\times10^8)}{5\\times10^{-7}}","explanation":""},{"latex":"E \\approx 3.98\\times10^{-19}\\ \\text{J} \\approx 2.48\\ \\text{eV}","explanation":""}]}';
UPDATE lesson_blocks SET kind = 'definition', data = '{"term":"Einstein''s photons","body":"Light comes in packets (photons) of energy $E = hf$, with $h = 6.626\\times10^{-34}$ J·s. One photon gives its energy to one electron, which needs at least the work function $\\phi$ to escape: $K_{max} = hf - \\phi$. 1 eV $= 1.602\\times10^{-19}$ J."}' WHERE id = 'blk_a4931917271861' AND kind = 'worked_example' AND data = '{"title":"250 nm UV light on sodium (φ = 2.28 eV)","steps":[{"latex":"E = \\tfrac{1240\\ \\text{eV·nm}}{250\\ \\text{nm}} \\approx 4.96\\ \\text{eV}","explanation":"The shortcut hc ≈ 1240 eV·nm."},{"latex":"K_{max} = 4.96 - 2.28 \\approx 2.68\\ \\text{eV}","explanation":""}]}';
UPDATE lesson_blocks SET kind = 'worked_example', data = '{"title":"Energy of a 500 nm (green) photon","steps":[{"latex":"E = \\tfrac{hc}{\\lambda}","explanation":""},{"latex":"E = \\tfrac{(6.626\\times10^{-34})(3\\times10^8)}{5\\times10^{-7}}","explanation":""},{"latex":"E \\approx 3.98\\times10^{-19}\\ \\text{J} \\approx 2.48\\ \\text{eV}","explanation":""}]}' WHERE id = 'blk_62ea2558166121' AND kind = 'callout' AND data = '{"tone":"application","title":"Where this shows up","body":"Solar cells, camera sensors and the photomultipliers in medical scanners all rely on photons freeing electrons. Einstein''s 1921 Nobel Prize was for this explanation."}';

-- Courses that now have published lessons are in development, not planned.
UPDATE courses SET status = 'in_development', updated_at = strftime('%Y-%m-%dT%H:%M:%SZ', 'now')
   WHERE status = 'planned' AND id IN (
     SELECT u.course_id FROM chapter_lessons cl JOIN lessons l ON l.id = cl.lesson_id
     JOIN chapters ch ON ch.id = cl.chapter_id JOIN units u ON u.id = ch.unit_id WHERE l.status = 'published');
